insert into public.recetario_recetas as t (fuente, codigo, clase, nombre, descripcion, rendimiento, unidad, alergenos, procedimiento, componentes, propuesta) values
  ('CARTA COCTELERÍA', 'C01', 'bebida', 'MARGARITA', 'Es un cóctel clásico mexicano hecho principalmente con tequila, licor de naranja (como triple sec) y jugo de limón. Se sirve normalmente en una copa con el borde escarchado con sal, lo que equilibra su sabor ácido, dulce y ligeramente salado.', 1, 'und', '{}'::text[], '1] Michelar y llevar la copa al congelador. 2] Agregar al primer tiempo (vaso pequeño) el tequila, el triplesec y el zumo de limon y al segundo tiempo (vaso grande) la mitad de hielo, tapar y shekear (agitar). 3] Una vez agitado vertir con ayuda del colador de oruga en la copa margarita anteriormente alistada. 4]coronar con una media luna de limon en uno de sus bordes y despachar.', '[{"tipo":"ing","codigo":"BAR-tequila-estandar","nombre":"tequila estándar","cantidad":60,"unidad":"ml","nota":"Tradicional con tequila estándar/premium con don julio"},{"tipo":"ing","codigo":"BAR-triple-sec","nombre":"triple sec","cantidad":30,"unidad":"ml","nota":"Tradicional contriple sec/premium con Cointreau"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"zumo de limon","cantidad":30,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Michelar y llevar la copa al congelador.","Agregar al primer tiempo (vaso pequeño) el tequila, el triplesec y el zumo de limon y al segundo tiempo (vaso grande) la mitad de hielo, tapar y shekear (agitar).","Una vez agitado vertir con ayuda del colador de oruga en la copa margarita anteriormente alistada. 4]coronar con una media luna de limon en uno de sus bordes y despachar."],"puntos":[{"tipo":"TEMPERATURA","texto":"Michelar y llevar la copa al congelador.","de":"paso"}],"observaciones":[],"metodo":"Shake","concepto":"COCTELERÍA CLASICA","decoracion":["Limón deshidratado","Sal (Michelado)","Tajin (Michelado)"],"presentacion":"Copa margarita previamente enfriada con tajin y sal (a preferencia del cliente) con una medialuna de limon","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"# 1","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C02', 'bebida', 'Negroni', 'El Negroni es un cóctel clásico italiano, fuerte y equilibrado, conocido por su sabor amargo, herbal y ligeramente dulce.', 1, 'und', '{}'::text[], '1] Agregar al mix in glass la ginebra, el campari y el vermouth rosso. 2] Llenar el mix in glass con hielo. 3] Refrescar con ayuda de la barspoom oro rosa 4] Una vez la mezcla se encuentre fria vertir con ayuda del colador de oruga en el vaso rockero (previamente enfriado). 5] Agregar un hielo cubo y decorar con una cascara de naranja en rosca y un deshidratado de naranja.', '[{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"Ginebra tanqueray","cantidad":30,"unidad":"ml","nota":"Tradicional con Ginebra tanqueray/premium con Hendricks"},{"tipo":"ing","codigo":"BAR-campari","nombre":"Campari","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vermouth-rosso-cinzano","nombre":"vermouth rosso cinzano","cantidad":30,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al mix in glass la ginebra, el campari y el vermouth rosso.","Llenar el mix in glass con hielo.","Refrescar con ayuda de la barspoom oro rosa","Una vez la mezcla se encuentre fria vertir con ayuda del colador de oruga en el vaso rockero (previamente enfriado).","Agregar un hielo cubo y decorar con una cascara de naranja en rosca y un deshidratado de naranja."],"puntos":[],"observaciones":[],"metodo":"Refrescado, escanseado","concepto":"COCTELERÍA CLASICA","decoracion":["1Und, Medialuna de naranja","1Und, cascara de naranja"],"presentacion":"Vaso rockero previamente congelado con 2 hielos perfect, medialuna de naranja en su interior y cascara de naranja enrollada la cual antes de coronar se pasa sutilmente por los bordes del vaso para impregnar su sabor","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"2.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C03', 'bebida', 'MOJITO', 'ligera, aromática y refrescante. Gracias a su combinación cítrica y herbal, es uno de los cócteles más populares del mundo, especialmente en climas cálidos.', 1, 'und', '{}'::text[], '1] Agregar directamente al vaso el ron, el zumo de limon, el sirope simple y las hojas de menta francesa. 2] Con ayuda del macerador metálico de punta negra majar muy bien las hierbas con los líquidos. 3] Agregar hielo en el vaso (full). 4] Agregar el dash soda (verificar que si es una recien abierta este bien aun de gas) al vaso y con ayuda del barspoom rosado remover el coctel de forma ascendente (la idea es que los ingredientes solidos queden en el coctel como si estuvieran flotando de manera estética. 5) Decorar con rodaja de limon fresco coronando con un cogollo de menta francesa y gotas de angostura (opcioinal si el cliente quiere).', '[{"tipo":"ing","codigo":"BAR-ron-bacardi-tradicional","nombre":"Ron Bacardi tradicional","cantidad":60,"unidad":"ml","nota":"Ron Bacardi tradicional/ (se solicita crear un ítem llamado base en este caso de mojito el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el ron a petición del cliente)"},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-hojas-de-menta-francesa","nombre":"Hojas de menta francesa","cantidad":8,"unidad":"und","nota":null},{"tipo":"ing","codigo":"BAR-soda-swepers","nombre":"Soda swepers","cantidad":null,"unidad":"dash","nota":"DASH"}]'::jsonb, '{"pasos":["Agregar directamente al vaso el ron, el zumo de limon, el sirope simple y las hojas de menta francesa.","Con ayuda del macerador metálico de punta negra majar muy bien las hierbas con los líquidos.","Agregar hielo en el vaso (full).","Agregar el dash soda (verificar que si es una recien abierta este bien aun de gas) al vaso y con ayuda del barspoom rosado remover el coctel de forma ascendente (la idea es que los ingredientes solidos queden en el coctel como si estuvieran flotando de manera estética.","Decorar con rodaja de limon fresco coronando con un cogollo de menta francesa y gotas de angostura (opcioinal si el cliente quiere)."],"puntos":[],"observaciones":["Ron Bacardi tradicional/ (se solicita crear un ítem llamado base en este caso de mojito el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el ron a petición del cliente)"],"metodo":"Directo","concepto":"COCTELERÍA CLASICA","decoracion":["1 und Cogollo de menta francesa","3und medialunas de limon","2gts Gotas de angostura bitters (opcional)"],"presentacion":"Vaso collins zac con rodajas de limon de modo que queden como flotando junto con los restos de las hojas majadas coronado con rodaja de limon fresco, cogollo de menta francesa y gotas de angostura (opcional si el cliente asi lo desea)","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"3.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C04', 'bebida', 'PISCO SOUR', 'El Pisco Sour es un cóctel emblemático de la coctelería sudamericana, muy representativo de Perú y Chile. En cuanto a sus sabores, ofrece un equilibrio entre lo ácido y lo dulce, con notas cítricas intensas del limón y el carácter aromático del pisco. La clara de huevo le da una textura suave y espumosa, mientras que las gotas de angostura añaden un toque especiado y fragante.', 1, 'und', '{}'::text[], '1] Agregar al shake la clara de huevo, el pisco, el zumo de limon y el sirope simple. 2] Sellar el shake sin hielo agregándole uno de los resortes del colador de oruga y shekear con mucha fuerza (hard shake). 3] Abrir el shake, retirar el resorte y agregar hielo hasta la mitad del segundo tiempo (vaso grande), tapar nuevamente y agitar con mucha fuerza hasta que el shake evidencie una fina capa de hielo. 4] Verter con ayuda del colador de oruga el coctel en un decanter pequeño (previamente congelado) y despachar a la mesa junto al vaso rockero con hielo perfect y el limon deshidratado decorado para ser vertido en mesa finalizando con las 3 gotas de angostura bitters como se aprecia en la imajen.', '[{"tipo":"ing","codigo":"BAR-pisco-acholado-demonio-de-los-andes","nombre":"Pisco acholado demonio de Los Andes","cantidad":60,"unidad":"ml","nota":"Tradicional con Pisco acholado demonio de Los Andes (se solicita crear un ítem llamado base pisco el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el destilado o licor a petición del cliente)"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope Simple","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-huevo","nombre":"Huevo","cantidad":1,"unidad":"und","nota":"Huevo (solo la clara)"}]'::jsonb, '{"pasos":["Agregar al shake la clara de huevo, el pisco, el zumo de limon y el sirope simple.","Sellar el shake sin hielo agregándole uno de los resortes del colador de oruga y shekear con mucha fuerza (hard shake).","Abrir el shake, retirar el resorte y agregar hielo hasta la mitad del segundo tiempo (vaso grande), tapar nuevamente y agitar con mucha fuerza hasta que el shake evidencie una fina capa de hielo.","Verter con ayuda del colador de oruga el coctel en un decanter pequeño (previamente congelado) y despachar a la mesa junto al vaso rockero con hielo perfect y el limon deshidratado decorado para ser vertido en mesa finalizando con las 3 gotas de angostura bitters como se aprecia en la imajen."],"puntos":[{"tipo":"TEMPERATURA","texto":"Verter con ayuda del colador de oruga el coctel en un decanter pequeño (previamente congelado) y despachar a la mesa junto al vaso rockero con hielo perfect y el limon deshidratado decorado para ser vertido en mesa finalizando con las 3 gotas de angostura bitters como se aprecia en la imajen.","de":"paso"}],"observaciones":["Tradicional con Pisco acholado demonio de Los Andes (se solicita crear un ítem llamado base pisco el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el destilado o licor a petición del cliente)"],"metodo":"Doble shake 1 seco,1 normal","concepto":"COCTELERÍA CLASICA","decoracion":["1 UND Limon deshidratado","3GTS Angostura bitters"],"presentacion":"Vaso rockero congelado con 2 hielos cubo y limon deshidratado el cual sale a mesa con el coctel preparado en un decanter congelado el cual se vierte en mesa y se corona con la angostura","alergenos_declarados":[],"alergenos_sugeridos":["Huevo"],"numero":"4.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C05', 'bebida', 'TOM COLLINS', 'Cóctel clásico y refrescante de la coctelería internacional, se caracteriza por ser ligero, cítrico y refrescante. El limón aporta una acidez brillante, el azúcar equilibra con un toque dulce y la ginebra añade notas herbales y botánicas. La soda le da una textura burbujeante que lo hace muy fácil de beber.', 1, 'und', '{}'::text[], '1] Agregar al vaso collins la ginebra, el sirope simple y el zumo de limon 2] Agregar hielo al tope del vaso. 3] Agregar la soda removiendo suavemente de manera ascendente, procurando no desgasificar el producto 4] Agregar el líquido de cereza de modo que no se mezcle si no que presenta un ligero contraste de colores sin combinarse. 4] Agregar el garnish (rodajas de futa fresca) de modo que quede flotando de forma estética en el medio del coctel. 5] Agregar el líquido de cereza de modo que no se mezcle si no que logre un ligero contraste de colores sin combinarse, coronar con deshidratado y cogollo y despachar.', '[{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"Ginebra Tanqueray","cantidad":60,"unidad":"ml","nota":"Tradicional con Ginebra Tanqueray (se solicita crear un ítem llamado base tom Collin''s el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el gin a petición del cliente)"},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope Simple","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo De Limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-soda-swepers","nombre":"Soda Swepers","cantidad":null,"unidad":"ml","nota":"DASH"},{"tipo":"ing","codigo":"BAR-liquido-de-cereza-en-vermouth","nombre":"Liquido de cereza en vermouth","cantidad":15,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al vaso collins la ginebra, el sirope simple y el zumo de limon","Agregar hielo al tope del vaso.","Agregar la soda removiendo suavemente de manera ascendente, procurando no desgasificar el producto","Agregar el líquido de cereza de modo que no se mezcle si no que presenta un ligero contraste de colores sin combinarse.","Agregar el garnish (rodajas de futa fresca) de modo que quede flotando de forma estética en el medio del coctel.","Agregar el líquido de cereza de modo que no se mezcle si no que logre un ligero contraste de colores sin combinarse, coronar con deshidratado y cogollo y despachar."],"puntos":[],"observaciones":["Tradicional con Ginebra Tanqueray (se solicita crear un ítem llamado base tom Collin''s el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el gin a petición del cliente)"],"metodo":"Directo","concepto":"COCTELERÍA CLASICA","decoracion":["2 Und medialunas de naranja","1 Und deshidratado de limon","1 Und cogollo de menta francesa"],"presentacion":"Vaso collin zac con las medialunas de naranja de modo que parezcan flotar en la preparacion ademas de el liquido de cereza el cual va vertido suavemente, que genere una tonalidad de cascada y finalizando o coronando con deshidratado de limon y cogollo de menta francesa.","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"5.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C06', 'bebida', 'DRY MARTINI', 'Es uno de los cócteles más clásicos y elegantes de la coctelería internacional, En cuanto a sus sabores, se caracteriza por ser seco, limpio y aromático. La ginebra aporta notas botánicas y herbales, mientras que el vermut seco añade un matiz ligeramente herbal y sutilmente amargo. El resultado es un cóctel refinado, intenso y equilibrado', 1, 'und', '{}'::text[], '1] Agregar al mix in glass la ginebra y el vermouth extra dry. 2] Agregar hielo (full) y refrescar con ayuda del barspoom largo rosado. 3] Agregar la mezcla en la copa martini premium (previamente congelada) y realizar un doble colado con el colador de oruga y el colador cunicular de malla fina coronando con el pincho de aceitunas y despachar.', '[{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"Ginebra Tanqueray","cantidad":90,"unidad":"ml","nota":"Tradicional con Ginebra Tanqueray (se solicita crear un ítem llamado base dry martini el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el gin a petición del cliente)"},{"tipo":"ing","codigo":"BAR-vermouth-extra-dry-cinzano","nombre":"Vermouth extra dry cinzano","cantidad":25,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-aceituna-verde-deshuesada","nombre":"Aceituna verde deshuesada","cantidad":3,"unidad":"und","nota":null},{"tipo":"ing","codigo":"BAR-liquido-del-encurtido-de-aceituna","nombre":"Liquido del encurtido de aceituna","cantidad":15,"unidad":"ml","nota":"Liquido del encurtido de aceituna (opcional)"}]'::jsonb, '{"pasos":["Agregar al mix in glass la ginebra y el vermouth extra dry.","Agregar hielo (full) y refrescar con ayuda del barspoom largo rosado.","Agregar la mezcla en la copa martini premium (previamente congelada) y realizar un doble colado con el colador de oruga y el colador cunicular de malla fina coronando con el pincho de aceitunas y despachar."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar la mezcla en la copa martini premium (previamente congelada) y realizar un doble colado con el colador de oruga y el colador cunicular de malla fina coronando con el pincho de aceitunas y despachar.","de":"paso"}],"observaciones":["Tradicional con Ginebra Tanqueray (se solicita crear un ítem llamado base dry martini el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el gin a petición del cliente)"],"metodo":"Escanseado O Refrescado, Doble colado","concepto":"Cocteleria clasica","decoracion":["Palillo de bar (para las aceitunas)"],"presentacion":"Copa martini premium congelada con un pincho con 3 aceitunas deshuesadas independiente si son moradas o verdes","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"6.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C07', 'bebida', 'COSMOPOLITAN', 'Coctel con un sabor refrescante, cítrico y ligeramente dulce, con un toque frutal y un final limpio.', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo del shake los arandanos, el vodka, el sirope simple y el zumo de limon 2] Macerar los arandanos hasta sesiorarnos que esten triturados, llenar el segundo tiempo con la mitad de hielo, tapar y agitar fuertemente (hard shake). 3] Seguido de eso hacer un doble colado, en la copa refrigerada decorar con cascaras de limon y 3 arandanos y despachar.', '[{"tipo":"ing","codigo":"BAR-vodka-absolut-y-premium-con-vodka-grey-g","nombre":"Vodka absolut y premium con vodka grey goose","cantidad":60,"unidad":"ml","nota":"Tradicional con Vodka absolut y premium con vodka grey goose"},{"tipo":"ing","codigo":"BAR-cointreau","nombre":"Cointreau","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-arandanos-frescos","nombre":"arandanos frescos","cantidad":8,"unidad":"und","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":10,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo del shake los arandanos, el vodka, el sirope simple y el zumo de limon","Macerar los arandanos hasta sesiorarnos que esten triturados, llenar el segundo tiempo con la mitad de hielo, tapar y agitar fuertemente (hard shake).","Seguido de eso hacer un doble colado, en la copa refrigerada decorar con cascaras de limon y 3 arandanos y despachar."],"puntos":[],"observaciones":[],"metodo":"Shake, Doble Colado","concepto":"Cocteleria Clasica","decoracion":["3 Und arandano fresco","1 und picho de decoracion","1 und deshidratado de limon"],"presentacion":"Copa martini previamente congelada con un pincho de cascara de limon y arándanos","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"7.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C08', 'bebida', 'APEROL SPRITZ', 'Este delicioso coctel cuenta con un sabor sumamente refrescante, ligeramente amargo, cítrico y burbujeante, con un toque dulce y herbal.', 1, 'und', '{}'::text[], '1] Agregar a la copa de vino previamente enfríada hielo a tope. 2] Agregar el Aperol. 3] Agregar el espumante de manera suave para evitar desperdiciar producto con el exceso de espuma. 4] Agregar el dash de soda removiendo de manera ascendente, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-aperol","nombre":"Aperol","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-soda-swepers","nombre":"Soda swepers","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-proseco","nombre":"Proseco","cantidad":90,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar a la copa de vino previamente enfríada hielo a tope.","Agregar el Aperol.","Agregar el espumante de manera suave para evitar desperdiciar producto con el exceso de espuma.","Agregar el dash de soda removiendo de manera ascendente, decorar y despachar."],"puntos":[],"observaciones":[],"metodo":"Directo","concepto":"COCTELERIA CLASICA","decoracion":["2 UND de media lunas de naranja"],"presentacion":"Copa de vino de cristal previamente congelada con una medialuna de naraja dentro la preparacion (como si flotara) y con la otra la pasamos por la boca de la copa y la ponemos encima","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"8.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C09', 'bebida', 'OLD FASHIONED', 'Este coctel clasico especificando que su destilado es bullet Bourbon tiene un sabor intenso y especiado, ligeramente dulce, con notas amaderadas, amargas y un toque cítrico elegante.', 1, 'und', '{}'::text[], '1] Agregar al mix in glass el whikey, el sirope simple y las gotas de angostura. 2] Agregar hielo a tope al mix in glass y refrescar con ayuda del barspoom rosado. 3] Verter con ayuda del colador de oruga en un vaso rockero con hielo cubo decorar con cascarade naranja y despachar.', '[{"tipo":"ing","codigo":"BAR-whisky-boullet-bourbon","nombre":"Whisky boullet bourbon","cantidad":60,"unidad":"ml","nota":"Tradicional con Whisky boullet bourbon (se solicita crear un ítem llamado base old fashioned el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el whisky a petición del cliente)"},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":10,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-bitters-de-angostura","nombre":"Bitters de angostura","cantidad":3,"unidad":"gota","nota":null}]'::jsonb, '{"pasos":["Agregar al mix in glass el whikey, el sirope simple y las gotas de angostura.","Agregar hielo a tope al mix in glass y refrescar con ayuda del barspoom rosado.","Verter con ayuda del colador de oruga en un vaso rockero con hielo cubo decorar con cascarade naranja y despachar."],"puntos":[],"observaciones":["Tradicional con Whisky boullet bourbon (se solicita crear un ítem llamado base old fashioned el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el whisky a petición del cliente)"],"metodo":"Refrescado, Escanseado","concepto":"COCTELERIA CLASICA","decoracion":["1 Und Naranja deshidratada"],"presentacion":"Vaso rockero previamente congelado con dos hielos cubo con una rodaja de naranja deshidratada y coronado con una cascara de naranja con la cual previemente labiaremos la boca del vaso y exprimiremos encima del coctel","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"9.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C10', 'bebida', 'MOSCOW MULE', 'Delicioso coctel con un sabor refrescante, con un ligero toque picante proporcionado por el jengibre ademas de notas citricas, con un toque dulce y burbujeante.', 1, 'und', '{}'::text[], '1] Agregar directamente al vaso de cobre el vodka, el zumo de limon y el sirope de jengibre. 2] Llenar el vaso de a tope de hielo. 3] Agregar la botella de ginger beer completa y remover de manera ascendente con ayuda de una barspoom, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-vodka-absolut-y","nombre":"Vodka absolut y","cantidad":60,"unidad":"ml","nota":"Tradicional con Vodka absolut y (se solicita crear un ítem llamado base Moscow mule el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el licor o destilado a petición del cliente)"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-jengibre","nombre":"Sirope de jengibre","cantidad":25,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginger-beer","nombre":"Ginger beer","cantidad":1,"unidad":"bot","nota":null}]'::jsonb, '{"pasos":["Agregar directamente al vaso de cobre el vodka, el zumo de limon y el sirope de jengibre.","Llenar el vaso de a tope de hielo.","Agregar la botella de ginger beer completa y remover de manera ascendente con ayuda de una barspoom, decorar y despachar."],"puntos":[],"observaciones":["Tradicional con Vodka absolut y (se solicita crear un ítem llamado base Moscow mule el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el licor o destilado a petición del cliente)"],"metodo":"Directo","concepto":"COCTELERIA CLASICA","decoracion":["1 Und Menta francesa","1 Und Lamina de jengibre","1 Und rodaja de limon"],"presentacion":"Vaso moscoe mule previamente enfriado coronado con cogollo de menta francesa limon deshidratado y lamina de jengibre","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"10.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C11', 'bebida', 'GIN AND TONIC', 'Un gin & tonic preparado con Tanqueray y tónica Ocean es una mezcla fresca, aromática y muy equilibrada, en nariz destaca el perfil clásico del gin: notas intensas de enebro, acompañadas por toques cítricos (limón y naranja) y un fondo herbal ligeramente especiado. Al mezclarse con la tónica Ocean, se realzan matices más suaves y refrescantes, con un burbujeo fino que aporta ligereza.', 1, 'und', '{}'::text[], 'Para la copa: agregar a la copa balon hielo a tope y en sus extremos laminas del ingrediente que el cliente elija ej: laminas de naranja, limon pepino, fresa, entre otras asi tambien sus cascaras, fuera de eso tambien contamos con variedad de botanicos como pimienta negra, de timut, de sechwan, rosada, clavo, canela, entre otros. Para el servicio: llevar la copa a la mesa junto a la tonica, a ginebra, una barspoom y el jeager, antes de servir rectificar el producto con el cliente seguido de medir en el jeager y vertir, finalizando con la tonica la cual vamos a agregar fr manera suave y con ayuda del barspoom removemos de manera ascendente.', '[{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"Ginebra Tanqueray","cantidad":60,"unidad":"ml","nota":"Tradicional con Ginebra Tanqueray/ en este caso se solicita en vez de crear la edición premium dejar la libertad de petición de gin al comensal y solamente anexar el gin como shot más la tónica de preferencia del cliente"},{"tipo":"ing","codigo":"BAR-agua-tonica-1976-ocean","nombre":"Agua tonica 1976 ocean","cantidad":1,"unidad":"bot","nota":"Agua tonica 1976 ocean/indian"}]'::jsonb, '{"pasos":["Para la copa: agregar a la copa balon hielo a tope y en sus extremos laminas del ingrediente que el cliente elija ej: laminas de naranja, limon pepino, fresa, entre otras asi tambien sus cascaras, fuera de eso tambien contamos con variedad de botanicos como pimienta negra, de timut, de sechwan, rosada, clavo, canela, entre otros. Para el servicio: llevar la copa a la mesa junto a la tonica, a ginebra, una barspoom y el jeager, antes de servir rectificar el producto con el cliente seguido de medir en el jeager y vertir, finalizando con la tonica la cual vamos a agregar fr manera suave y con ayuda del barspoom removemos de manera ascendente."],"puntos":[],"observaciones":["Tradicional con Ginebra Tanqueray/ en este caso se solicita en vez de crear la edición premium dejar la libertad de petición de gin al comensal y solamente anexar el gin como shot más la tónica de preferencia del cliente"],"metodo":"Directo","concepto":"COCTELERIA CLASICA","decoracion":["En este caso los ingredientes pueden ser muy variados ya que la especificacion la decide, entre ellas tenemos naranja-limon(cascara, rodaja y medialuna) pimienta rosada, gorfa, dulce, cardamomo, pepino, entre otros"],"presentacion":"Copa balon previemente congelada con full hielo decorada con los topings a eleccion del comensal","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"11.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C12', 'bebida', 'LYCHEE MARTINI', 'Este es un cóctel elegante, exótico y delicadamente aromático que destaca por su suavidad y perfil afrutado. sedoso y ligeramente dulce, con un equilibrio muy agradable entre la frescura del licor base y la jugosidad del lichi', 1, 'und', '{}'::text[], '1] Agregar al mix in glass el vodka, el soho y el jugo del lychee. 2] Llenar el mix in glass con hielo a tope. 3] Refrescar con ayuda de la barspoom rosada y verter en la copa, decorar con el pincho con lychees y despachar', '[{"tipo":"ing","codigo":"BAR-vodka-absolut","nombre":"Vodka absolut","cantidad":60,"unidad":"ml","nota":"Tradicional con Vodka absolut / premium con grey goose"},{"tipo":"ing","codigo":"BAR-soho","nombre":"Soho","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-lychee","nombre":"Sirope de Lychee","cantidad":30,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al mix in glass el vodka, el soho y el jugo del lychee.","Llenar el mix in glass con hielo a tope.","Refrescar con ayuda de la barspoom rosada y verter en la copa, decorar con el pincho con lychees y despachar"],"puntos":[],"observaciones":[],"metodo":"Refrescado, Escanseado","concepto":"COCTELERIA CLASICA","decoracion":["1 Und Palillo decorativo","2 Und lychee"],"presentacion":"Copa martini premium preciamente congelada acompañada con picho de lychees","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"12.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C13', 'bebida', 'MANHATAN', 'El Manhattan es uno de los cócteles más clásicos y sofisticados del mundo Es una bebida directa, elegante y potente, con una textura sedosa y ligeramente herbasea', 1, 'und', '{}'::text[], '1] Agregar al mix in glass el whiskey, el vermouth rosso, el sirope simple y las gotas de angostura. 2] Agregar al mix in glass hielo a tope y con ayuda del barspoom rosada refrescar. 3] Una vez refrescada la mezcla vertir en la copa martini previamente enfriada, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-whiskey-bullet-bourbon-y","nombre":"Whiskey bullet bourbon y","cantidad":60,"unidad":"ml","nota":"Tradicional con Whiskey bullet bourbon y (se solicita crear un ítem llamado base Manhattan el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el whisky a petición del cliente)"},{"tipo":"ing","codigo":"BAR-vermouth-rosso","nombre":"Vermouth rosso","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":10,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-angostura-bitters","nombre":"Angostura bitters","cantidad":2,"unidad":"gts","nota":null}]'::jsonb, '{"pasos":["Agregar al mix in glass el whiskey, el vermouth rosso, el sirope simple y las gotas de angostura.","Agregar al mix in glass hielo a tope y con ayuda del barspoom rosada refrescar.","Una vez refrescada la mezcla vertir en la copa martini previamente enfriada, decorar y despachar."],"puntos":[],"observaciones":["Tradicional con Whiskey bullet bourbon y (se solicita crear un ítem llamado base Manhattan el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el whisky a petición del cliente)"],"metodo":"Escanseado, Refrecado","concepto":"COCTELERIA CLASICA","decoracion":["1 Und Cascara de limon","1 Und cereza macerada en vermouth","Pincho decoratico","1 Und deshidratado de limon"],"presentacion":"Copa martini previamente congelada con cascara de limon enroscada (se pasa por el rededor de la copa labiandola y se exprime en cima del cocel ya servido) con pincho de deshidratado y cereza macerada en vermouth","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"13.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C14', 'bebida', 'CAIPIRIÑA', 'Caipiriña: ¡Un "te quiero" brasileño, cítrico y dulce en tu boca Imagínate un cóctel que es pura frescura vibrante, ideal para un día de sol. Su aroma es una explosión directa de lima fresca y aceites esenciales de la cáscara, mezclado con las notas vegetales y dulces de la caña.', 1, 'und', '{}'::text[], '1] Cortar las puntas de un limon,seguido de cortarlo a la mitad y asi mismo una de estas mitades la cortaremos en 4 partes y la agregamos al primer tiempo del shake. 2] Agregamo a este mismo la cachaza, el sirope simple y el zumo de limon. 3] Llenamos el segundo tiempo (vaso grande del shake) con hielo a la mitad. 4] Tapamos muy bien y procedemos a shekear en esta ocasion con mucha fuerza pero por un corto tiempo que no se vayan a deshacer mucho los hielos en el interior del shake. 5] Seguido de eso vertimos directamente al vaso rockero previemente congelado incluyendo los trozos de limon y hielo (el vaso debe estar labiado previamente si el cliente lo quiere asi), decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-cazhaza-y","nombre":"Cazhaza y","cantidad":60,"unidad":"ml","nota":"Tradicional con Cazhaza y (se solicita crear un ítem llamado base caipirinha el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el destilado a petición del cliente)"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":10,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-cascos-de-limon","nombre":"Cascos de limon","cantidad":4,"unidad":"und","nota":null}]'::jsonb, '{"pasos":["Cortar las puntas de un limon,seguido de cortarlo a la mitad y asi mismo una de estas mitades la cortaremos en 4 partes y la agregamos al primer tiempo del shake.","Agregamo a este mismo la cachaza, el sirope simple y el zumo de limon.","Llenamos el segundo tiempo (vaso grande del shake) con hielo a la mitad.","Tapamos muy bien y procedemos a shekear en esta ocasion con mucha fuerza pero por un corto tiempo que no se vayan a deshacer mucho los hielos en el interior del shake.","Seguido de eso vertimos directamente al vaso rockero previemente congelado incluyendo los trozos de limon y hielo (el vaso debe estar labiado previamente si el cliente lo quiere asi), decorar y despachar."],"puntos":[{"tipo":"TEMPERATURA","texto":"Seguido de eso vertimos directamente al vaso rockero previemente congelado incluyendo los trozos de limon y hielo (el vaso debe estar labiado previamente si el cliente lo quiere asi), decorar y despachar.","de":"paso"}],"observaciones":["Tradicional con Cazhaza y (se solicita crear un ítem llamado base caipirinha el cual tenga costeado los ingredientes mencionados en esta misma tabla y de esa forma se pueda ofrecer el destilado a petición del cliente)"],"metodo":"Shake","concepto":"COCTELERIA CLASICA","decoracion":["Azucar con acido citrico (opcinal medio labiado)","2 Und medialunas de limon","2 Und hojas de menta francesa"],"presentacion":"Vaso rockero previamente congelado con los trozos resultantes del agitado que queden en el interior coronado con medialunas de naranja y las hojas de mentas (aromatizamos con ella la boca del vaso","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"14.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C15', 'bebida', 'ORGASMO', 'Este cóctel se caracteriza por su sabor dulce y cremoso y su textura aterciopelada y suave. Ademas de notas con toques de café y almendras, el Kahlúa aporta notas de café robustas, mientras que el Amaretto añade un sutil sabor a almendras tostadas.', 1, 'und', '{}'::text[], '1] Agregar a la licuadora el baileys, el licor de cafe y el amareto. 2] Agregar hielo (120GR) de modo que el total de la mezcla mida 200ML de la licuadora ninja (sumamente importante que para esta mezcla el hielo sea bien compacto grande y congelado). 3] Ubicar el botón frozen de la licuadora oprimirlo y finalizar al lograr un aspecto frozen (fapeado) en la mezcla. 4] Vertir en la copa Martini previamente decorada con una espiral de chocolate liquido hersey’s, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-licor-de-cafe-coloma","nombre":"Licor de café coloma","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-amareto-dissarono","nombre":"Amareto dissarono","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-baeileys","nombre":"Baeileys","cantidad":45,"unidad":"ml","nota":"Baeileys/ se sugiere crear la opción de venta con la botella de dissarono velvet"}]'::jsonb, '{"pasos":["Agregar a la licuadora el baileys, el licor de cafe y el amareto.","Agregar hielo (120GR) de modo que el total de la mezcla mida 200ML de la licuadora ninja (sumamente importante que para esta mezcla el hielo sea bien compacto grande y congelado).","Ubicar el botón frozen de la licuadora oprimirlo y finalizar al lograr un aspecto frozen (fapeado) en la mezcla.","Vertir en la copa Martini previamente decorada con una espiral de chocolate liquido hersey’s, decorar y despachar."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar hielo (120GR) de modo que el total de la mezcla mida 200ML de la licuadora ninja (sumamente importante que para esta mezcla el hielo sea bien compacto grande y congelado).","de":"paso"}],"observaciones":["Baeileys/ se sugiere crear la opción de venta con la botella de dissarono velvet"],"metodo":"Licuado,Frozen","concepto":"COCTELERIA CLASICA","decoracion":["1 Und Cereza maceradas en vermouth","1 Und garnitura de limon","Salsa de chocolate hersey´s (para decoracion)"],"presentacion":"Copa martini diamante previamente congelada con lineas de salsa de chocolate herseys antes de agregar el coctel frozen seuido de un corazon dibujado con la misma de chocolate salsa herseys","alergenos_declarados":[],"alergenos_sugeridos":["Frutos secos","Sulfitos"],"numero":"15.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C16', 'bebida', 'STELLA DI FIORE', 'Exquisitas notas frescas y herbales de la menta francesa, seguidas de un aroma frutal a bayas y un toque cítrico y picante del jengibre.', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo (vaso corto) del shake las hojas de menta francecsa con los arándanos frescos, el sirope simple y el zumo de limón y majar muy bien con ayuda del macerador y un dash de ginger beer. 2] Una vez macerado verter en el vaso de cobre con ayuyda del colador de oruga y llenar a tope de hielo. 3] Agregar la botella a su totalidad de ginger beer remover suavemente de manera ascendente, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-menta-francesa","nombre":"Menta francesa","cantidad":8,"unidad":"und (hojas)","nota":"Menta francesa (sugerencia de envenenado gin y vodka)"},{"tipo":"ing","codigo":"BAR-arandano-fresco","nombre":"Arandano fresco","cantidad":8,"unidad":"und","nota":null},{"tipo":"ing","codigo":"BAR-zuno-de-limon","nombre":"Zuno de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginger-beer","nombre":"Ginger beer","cantidad":1,"unidad":"bot","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto) del shake las hojas de menta francecsa con los arándanos frescos, el sirope simple y el zumo de limón y majar muy bien con ayuda del macerador y un dash de ginger beer.","Una vez macerado verter en el vaso de cobre con ayuyda del colador de oruga y llenar a tope de hielo.","Agregar la botella a su totalidad de ginger beer remover suavemente de manera ascendente, decorar y despachar."],"puntos":[],"observaciones":[],"metodo":"Macerado, Directo","concepto":"MOKTEL''S","decoracion":["1 Und rodaja de limon","3 Und arandano fresco","1 Und cogollo de menta francesa"],"presentacion":"Vaso de moscow mule coronado con rodaja de limon y 3 arandans en el centro y cogollo de menta francesa a un extremo","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"16.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C17', 'bebida', 'STELLA SU SOLEI', 'Espectacular mocktail complejo y equilibrado: dulce y tropical al inicio, con un corazón especiado envolvente, y un final sensual, refrescante, cítrico y ligeramente amargo.', 1, 'und', '{}'::text[], '1] Agregar el sirope y el zumo de limon a la copa balon. 2] Agregar hielo a tope a la copa. 3] Agregar la tonica pink y con ayuda del barspoom remover de manera ascendente, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-sirpe-stella-du-solei","nombre":"Sirpe stella du solei","cantidad":90,"unidad":"ml","nota":"Sirpe stella du solei (sugerencia de envenenado ron y tequila)"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-agua-tonica-pink","nombre":"Agua tonica pink","cantidad":1,"unidad":"bot","nota":null}]'::jsonb, '{"pasos":["Agregar el sirope y el zumo de limon a la copa balon.","Agregar hielo a tope a la copa.","Agregar la tonica pink y con ayuda del barspoom remover de manera ascendente, decorar y despachar."],"puntos":[],"observaciones":[],"metodo":"Directo","concepto":"MOKTEL''S","decoracion":["1 und cogollo menta francesa","Papel de Maracuya","1 UND rodaja de citrico disponible (para su interior)"],"presentacion":"Copa balon corrugada decorada un papel de Maracuya y completada con cogollo de menta francesa","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"17.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C18', 'bebida', 'STELLA DI MANGO', 'deliciosa y compleja mezcla donde el dulzor jugoso y tropical del mango se funde con la acidez suave y el carácter frutal de la fresa sumado al matiz herbal, fresco y ligeramente anisado del eneldo, elevamos la mezcla a un nuevo y contndente perfil aromático más sofisticado.', 1, 'und', '{}'::text[], '1] Agregar el sirope y el zumo de limon a la copa balon. 2] Agregar hielo a tope a la copa. 3] Agregar la tonica pink y con ayuda del barspoom remover de manera ascendente, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-sirope-stella-di-mango","nombre":"Sirope stella di mango","cantidad":90,"unidad":"ml","nota":"Sirope stella di mango (sugerencia de envenenado ron y tequila)"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-tonica-pink","nombre":"Tonica pink","cantidad":1,"unidad":"bot","nota":null}]'::jsonb, '{"pasos":["Agregar el sirope y el zumo de limon a la copa balon.","Agregar hielo a tope a la copa.","Agregar la tonica pink y con ayuda del barspoom remover de manera ascendente, decorar y despachar."],"puntos":[],"observaciones":[],"metodo":"Directo","concepto":"MOKTEL''S","decoracion":["1 UND cogoll menta francesa","1 UND papel de frutas (o rodaja de citrico)","1 UND rodaja de citricos"],"presentacion":"Copa balon corrugada decorada un papel de Mango y completada con cogollo de menta francesa","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"18.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C19', 'bebida', 'STELLA DI ROSSO', 'Este mocktail combina en su reducción notas dulces, ácidas y casi vinosas equilibrado con miel de abejas y un sutil toque de vinagre balsámico, dando una profundidad agridulce; ademas la ginger beer, añade efervescencia y un picante cálido, logrando una bebida intensa, refrescante y con un final vibrante y especiado.', 1, 'und', '{}'::text[], '1] Agregar el sirope y el zumo de limon a la copa balon. 2] Agregar hielo a tope a la copa. 3] Agregar la ginger beer y con ayuda del barspoom remover de manera ascendente, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-sirope-reduccione-di-rosso","nombre":"Sirope reduccione di rosso","cantidad":90,"unidad":"ml","nota":"Sirope reduccione di rosso (sugerencia de envenenado whisky y ron)"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginger-beer","nombre":"Ginger Beer","cantidad":1,"unidad":"bot","nota":null}]'::jsonb, '{"pasos":["Agregar el sirope y el zumo de limon a la copa balon.","Agregar hielo a tope a la copa.","Agregar la ginger beer y con ayuda del barspoom remover de manera ascendente, decorar y despachar."],"puntos":[],"observaciones":[],"metodo":"Directo","concepto":"MOKTEL''S","decoracion":["1 UND papel de frutas (o rodaja de citrico disponible)","1 UND cogollo menta francesa","1 UND rodaja de citrico"],"presentacion":"Copa balon decorada con una lamina de citrico en su interior y una en su exterior preferiblemente lamina de fresa completada con cogollo de menta francesa y papel de fruta encima de la copa (si no hay disponible papel de fruta se corona con lamina de fresa)","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"19.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C20', 'bebida', 'STELLA DI LYCHEE', 'Es un cóctel refrescante y elegante, con burbujas finas, donde el lichie macerado aporta una dulzura exótica y floral fusionando la suavidad del sirope de vainilla, y con zumo de limón aporta una acidez brillante; al final, la tónica pink añade un ligero amargor y notas frutales, creando una bebida armoniosa y ligera ideal como aperitivo en una tarde cálida.', 1, 'und', '{}'::text[], '1) Agregar a la copa balon 1UND de lycheel jugo de lychhe 2) Agregar hielo a a tope. 3) Agregar la totalidad de la tonica pink y con ayuda del barspoom mezclar de forma ascendente. 4) Agregar como decoracion una lamina de limon o naranja en su interior y coronar con menta francesa deshidratado de limon y un lychee, despachar.', '[{"tipo":"ing","codigo":"BAR-sirope-de-lychee","nombre":"Sirope de Lychee","cantidad":90,"unidad":"ml","nota":"Sirope de Lychee (sugerencia de envenenado vodka y ginebra)"},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de Limón","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-mil-976-ginger-beer","nombre":"Mil 976 Ginger Beer","cantidad":1,"unidad":"bot","nota":null}]'::jsonb, '{"pasos":["Agregar a la copa balon 1UND de lycheel jugo de lychhe","Agregar hielo a a tope.","Agregar la totalidad de la tonica pink y con ayuda del barspoom mezclar de forma ascendente.","Agregar como decoracion una lamina de limon o naranja en su interior y coronar con menta francesa deshidratado de limon y un lychee, despachar."],"puntos":[],"observaciones":[],"metodo":"Directo","concepto":"MOKTEL´S","decoracion":["1 UND Lychee","1 UND Cogollo Menta Francesa","2 UND Media Luna naranja"],"presentacion":"Copa balon previamente enfriada con una media luna de naranja en su interior y coronada con una unidad de lichee una rodaja de limon y un cogollo de menta francesa","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"20.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C21J', 'bebida', 'SANGRIA CHOCOLATE (JARRA)', 'Sabor complejo y equilibrado,el tequila de chocolate aporta notas dulces y de cacao que se combinan con la calidez del ron y la neutralidad del vodka, mientras el zumo de naranja brinda frescura y acidez, realzando sus sabores;la ginger da efervecencia y especiado, y la deliciosa fruta picada aporta dulzor, y una textura frutal vibrante, resultado: una bebida refrescante, aromática y con capas de sabor que se perciben en cada sorbo,', 1, 'und', '{}'::text[], '1). Agregar al decanter grande la fruta suelta, los licores, la ginger y el zumo de naranja congelado (este debe estar cortado en trozos pequeños para una optima dilucion. 2). Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca. 3] Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas).', '[{"tipo":"ing","codigo":"BAR-tequila-de-chocolate","nombre":"Tequila De Chocolate","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron-bacardi-anejo","nombre":"Ron Bacardi Añejo","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vodka-absolut","nombre":"Vodka Absolut","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naraja","nombre":"Zumo De Naraja","cantidad":150,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginger-swepers","nombre":"Ginger Swepers","cantidad":null,"unidad":"bot","nota":"med"},{"tipo":"ing","codigo":"BAR-vino-rosaleda","nombre":"Vino Rosaleda","cantidad":1,"unidad":"bot","nota":"Vino Rosaleda (A Eleccion Del Comensal"},{"tipo":"ing","codigo":"BAR-picadillo-de-sangria-tradicional","nombre":"Picadillo De Sangria tradicional","cantidad":150,"unidad":"g","nota":null}]'::jsonb, '{"pasos":["Agregar al decanter grande la fruta suelta, los licores, la ginger y el zumo de naranja congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas)."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar al decanter grande la fruta suelta, los licores, la ginger y el zumo de naranja congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","de":"paso"},{"tipo":"TEMPERATURA","texto":"Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","de":"paso"}],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGIRAS","decoracion":[],"presentacion":"JARRA:Decanter grande con picadillo y los liquidos menos el vino, este se sirve a modo de experiencia al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"21.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C21C', 'bebida', 'SANGRIA CHOCOLATE (COPA)', 'Sabor complejo y equilibrado,el tequila de chocolate aporta notas dulces y de cacao que se combinan con la calidez del ron y la neutralidad del vodka, mientras el zumo de naranja brinda frescura y acidez, realzando sus sabores;la ginger da efervecencia y especiado, y la deliciosa fruta picada aporta dulzor, y una textura frutal vibrante, resultado: una bebida refrescante, aromática y con capas de sabor que se perciben en cada sorbo,', 1, 'und', '{}'::text[], '1) Agregar la fruta picada, los licores y el zumo denaranja a un primer tiempo (vaso pequeño del shake) y presionar con ayuda del macerador con mucha suavidad para soltar la fruta mas no aplastarla. 2) Pasar el contenido a la copa y añadir 90 gr de hielo. 3) Agregar el la ginger y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa 4) Agregar con cuidado de no mezclar la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar.', '[{"tipo":"ing","codigo":"BAR-tequila-de-chocolate","nombre":"Tequila De Chocolate","cantidad":25,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron-bacardi-anejo","nombre":"Ron Bacardi Añejo","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vodka-absolut","nombre":"Vodka Absolut","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naraja","nombre":"Zumo De Naraja","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginger-swepers","nombre":"Ginger Swepers","cantidad":null,"unidad":"dash","nota":"DASH"},{"tipo":"ing","codigo":"BAR-vino-rosaleda","nombre":"Vino Rosaleda","cantidad":150,"unidad":"ml","nota":"Vino Rosaleda (A Eleccion Del Comensal"},{"tipo":"ing","codigo":"BAR-picadillo-de-sangria-tradicional","nombre":"Picadillo De Sangria tradicional","cantidad":2,"unidad":"cucharas","nota":null}]'::jsonb, '{"pasos":["Agregar la fruta picada, los licores y el zumo denaranja a un primer tiempo (vaso pequeño del shake) y presionar con ayuda del macerador con mucha suavidad para soltar la fruta mas no aplastarla.","Pasar el contenido a la copa y añadir 90 gr de hielo.","Agregar el la ginger y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa","Agregar con cuidado de no mezclar la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar."],"puntos":[],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGIRAS","decoracion":[],"presentacion":"JARRA:Decanter grande con picadillo y los liquidos menos el vino, este se sirve a modo de experiencia al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"21.5","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C22J', 'bebida', 'SANGRIA VAINILLA (VAINILLA)', 'El alma de esta sangría nace de un delicado licor artesanal de vainilla, seductor y aromático, que envuelve cada sorbo con notas suaves, cálidas y ligeramente especiadas. Su carácter se fusiona con ron y vodka para aportar profundidad y equilibrio, mientras el zumo de naranja y el ginger despiertan una frescura vibrante en boca. La mezcla se enriquece con un picadillo de manzana Gala, manzana verde, piña y fresas frescas, creando un contraste perfecto entre dulzor tropical y acidez natural. Finalizada con vino tinto, rosado o blanco, esta creación transforma la vainilla en la protagonista absoluta de una experiencia elegante, refrescante y profundamente artesanal.', 1, 'und', '{}'::text[], '1). Agregar al decanter grande la fruta suelta, los licores, la ginger y el zumo de naranja congelado (este debe estar cortado en trozos pequeños para una optima dilucion. 2). Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca. 3] Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas).', '[{"tipo":"ing","codigo":"BAR-licor-de-vainilla","nombre":"Licor De Vainilla","cantidad":120,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron-bacardi-anejo","nombre":"Ron Bacardi Añejo","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naraja","nombre":"Zumo De Naraja","cantidad":200,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginger-swepers","nombre":"Ginger Swepers","cantidad":null,"unidad":"bot","nota":"med"},{"tipo":"ing","codigo":"BAR-vino-rosaleda","nombre":"Vino Rosaleda","cantidad":1,"unidad":"bot","nota":"Vino Rosaleda (A Eleccion Del Comensal)"},{"tipo":"ing","codigo":"BAR-picadillo-de-sangria-tradicional","nombre":"Picadillo De Sangria tradicional","cantidad":150,"unidad":"g","nota":null}]'::jsonb, '{"pasos":["Agregar al decanter grande la fruta suelta, los licores, la ginger y el zumo de naranja congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas)."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar al decanter grande la fruta suelta, los licores, la ginger y el zumo de naranja congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","de":"paso"},{"tipo":"TEMPERATURA","texto":"Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","de":"paso"}],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGRÍAS","decoracion":[],"presentacion":"JARRA:Decanter grande con picadillo y los liquidos menos el vino, este se sirve a modo de experiencia al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"22.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C22C', 'bebida', 'SANGRIA VAINILLA (COPA)', 'El alma de esta sangría nace de un delicado licor artesanal de vainilla, seductor y aromático, que envuelve cada sorbo con notas suaves, cálidas y ligeramente especiadas. Su carácter se fusiona con ron y vodka para aportar profundidad y equilibrio, mientras el zumo de naranja y el ginger despiertan una frescura vibrante en boca. La mezcla se enriquece con un picadillo de manzana Gala, manzana verde, piña y fresas frescas, creando un contraste perfecto entre dulzor tropical y acidez natural. Finalizada con vino tinto, rosado o blanco, esta creación transforma la vainilla en la protagonista absoluta de una experiencia elegante, refrescante y profundamente artesanal.', 1, 'und', '{}'::text[], '1) Agregar la fruta picada, los licores y el zumo de limon a un primer tiempo (vaso pequeño del shake) y presionar con ayuda del macerador con mucha suavidad para soltar la fruta. 2) Pasar el contenido a la copa y añadir 90 gr de hielo. 3) Agregar el la ginger y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa 4) Agregar con cuidado de no mezclar la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar.', '[{"tipo":"ing","codigo":"BAR-licor-de-vainilla","nombre":"Licor De Vainilla","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron-bacardi-anejo","nombre":"Ron Bacardi Añejo","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naraja","nombre":"Zumo De Naraja","cantidad":90,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginger-swepers","nombre":"Ginger Swepers","cantidad":null,"unidad":"dash","nota":"dash"},{"tipo":"ing","codigo":"BAR-vino-rosaleda","nombre":"Vino Rosaleda","cantidad":150,"unidad":"ml","nota":"Vino Rosaleda (A Eleccion Del Comensal"},{"tipo":"ing","codigo":"BAR-picadillo-de-sangria-tradicional","nombre":"Picadillo De Sangria tradicional","cantidad":2,"unidad":"cucharas","nota":null}]'::jsonb, '{"pasos":["Agregar la fruta picada, los licores y el zumo de limon a un primer tiempo (vaso pequeño del shake) y presionar con ayuda del macerador con mucha suavidad para soltar la fruta.","Pasar el contenido a la copa y añadir 90 gr de hielo.","Agregar el la ginger y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa","Agregar con cuidado de no mezclar la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar."],"puntos":[],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGIRAS","decoracion":[],"presentacion":"Copa balon corugada con una doble tonalidad o contraste entre los licores con el picadillo de fruta y el vino junto a un coronado estetico","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"22.5","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C23J', 'bebida', 'MORFEO PEE(JARRA)', 'El alma de esta sangría nace de un delicado licor artesanal de manzanilla, protagonista de una mezcla elegante y aromática junto a Licor 43 y ron, que aporta notas florales, dulces y cálidamente herbales. El zumo de naranja y un sutil toque de ginger realzan la frescura tropical del picadillo de maracuyá, granadilla, piña y uchuva, creando un equilibrio vibrante entre acidez, dulzor y frescura. La experiencia se intensifica con una reducción artesanal de maracuyá y granadilla, que aporta profundidad y un final exótico y seductor en cada sorbo.', 1, 'und', '{}'::text[], '1). Agregar al decanter grande la fruta suelta, el sirope, los licores y el zumo de mandarina congelado (este debe estar cortado en trozos pequeños para una optima dilucion. 2). Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca. 3] Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas).', '[{"tipo":"ing","codigo":"BAR-licor-de-manzanilla","nombre":"Licor De manzanilla","cantidad":90,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron-bacardi-anejo","nombre":"Ron Bacardi añejo","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-43","nombre":"licor 43","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naranja","nombre":"zumo de naranja","cantidad":150,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-morfeo-pee","nombre":"sirope morfeo pee","cantidad":90,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-rosaleda","nombre":"vino rosaleda","cantidad":1,"unidad":"bot","nota":"vino rosaleda (rosado o blanco)"},{"tipo":"ing","codigo":"BAR-picadillo-morfeo-pee","nombre":"Picadillo morfeo pee","cantidad":150,"unidad":"g","nota":null}]'::jsonb, '{"pasos":["Agregar al decanter grande la fruta suelta, el sirope, los licores y el zumo de mandarina congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas)."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar al decanter grande la fruta suelta, el sirope, los licores y el zumo de mandarina congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","de":"paso"},{"tipo":"TEMPERATURA","texto":"Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","de":"paso"}],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGIRAS","decoracion":[],"presentacion":"JARRA:Decanter grande con picadillo y los liquidos menos el vino, este se sirve a modo de experiencia al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"23.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C23C', 'bebida', 'MORFEO PEE (COPA)', 'El alma de esta sangría nace de un delicado licor artesanal de manzanilla, protagonista de una mezcla elegante y aromática junto a Licor 43 y ron, que aporta notas florales, dulces y cálidamente herbales. El zumo de naranja y un sutil toque de ginger realzan la frescura tropical del picadillo de maracuyá, granadilla, piña y uchuva, creando un equilibrio vibrante entre acidez, dulzor y frescura. La experiencia se intensifica con una reducción artesanal de maracuyá y granadilla, que aporta profundidad y un final exótico y seductor en cada sorbo.', 1, 'und', '{}'::text[], '1) Agregar a un primer tiempo (vaso pequeño del shake) la fruta picada, los licores y el zumo de mandarina y presionar con ayuda del macerador con mucha suavidad para soltar la fruta. 2) Pasar el contenido a la copa y añadir 90 gr de hielo. 3) Agregar el sirope de morfeo pee y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa 4) Agregar con cuidado la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar.', '[{"tipo":"ing","codigo":"BAR-licor-de-manzanilla","nombre":"Licor De manzanilla","cantidad":25,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron-bacardi-anejo","nombre":"Ron Bacardi añejo","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-43","nombre":"licor 43","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naranja","nombre":"zumo de naranja","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-morfeo-pee","nombre":"Sirope Morfeo Pee","cantidad":25,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-rosaleda","nombre":"Vino rosaleda","cantidad":150,"unidad":"ml","nota":"Vino rosaleda (blanco o rosado)"},{"tipo":"ing","codigo":"BAR-picadillo-morfeo-pee","nombre":"Picadillo morfeo pee","cantidad":2,"unidad":"cda","nota":null}]'::jsonb, '{"pasos":["Agregar a un primer tiempo (vaso pequeño del shake) la fruta picada, los licores y el zumo de mandarina y presionar con ayuda del macerador con mucha suavidad para soltar la fruta.","Pasar el contenido a la copa y añadir 90 gr de hielo.","Agregar el sirope de morfeo pee y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa","Agregar con cuidado la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar."],"puntos":[],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGIRAS","decoracion":[],"presentacion":"Copa balon corugada con una doble tonalidad o contraste entre los licores con el picadillo de fruta y el vino junto a un coronado estetico","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"23.5","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C25J', 'bebida', 'GREEN VELVET (JARRA)', 'Inspirada en la lulada valluna, de perfil fresco, cítrico y ligeramente especiado, donde el lulo, el kiwi y el melón aportan una base tropical que se mezcla con la intensidad del limoncello y el licor de limoncillo, mientras el ron y el vino blanco equilibran la mezcla; el zumo de mandarina y el sirope de clavo y canela realzan sus notas aromáticas, dando como resultado una bebida vibrante, refrescante y bien balanceada', 1, 'und', '{}'::text[], '1). Agregar al decanter grande la fruta suelta, el sirope, los licores y el zumo de mandarina congelado (este debe estar cortado en trozos pequeños para una optima dilucion. 2). Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca. 3] Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas).', '[{"tipo":"ing","codigo":"BAR-picadillo-green-velvet","nombre":"Picadillo green velvet","cantidad":150,"unidad":"g","nota":null},{"tipo":"ing","codigo":"BAR-limoncello","nombre":"Limoncello","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-limoncillo","nombre":"Licor de limoncillo","cantidad":90,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-green-velvet","nombre":"Sirope green velvet","cantidad":90,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-blanco","nombre":"Vino blanco","cantidad":1,"unidad":"bot","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naranjja","nombre":"Zumo de naranjja","cantidad":120,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron","nombre":"Ron","cantidad":30,"unidad":"g","nota":null}]'::jsonb, '{"pasos":["Agregar al decanter grande la fruta suelta, el sirope, los licores y el zumo de mandarina congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","Indicar al asesor de servicio el vertido de la totalidad de la botella de vino seguido del mezclado y el servido procurando que parte de la fruta de la jarra se distribuya por el numero de servicios(copas)."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar al decanter grande la fruta suelta, el sirope, los licores y el zumo de mandarina congelado (este debe estar cortado en trozos pequeños para una optima dilucion.","de":"paso"},{"tipo":"TEMPERATURA","texto":"Revolver con cuidado la jarra de modo que se mezclen los ingredientes y alistar los servicios notificados por el asesor de servicio (copa balon corugada con 2 cucharadas de fruta picada, hielo hasta la mitad (que este se encuentre bien congelado y de un tamaño mediano, media luna de naranja en el interior y coronada con deshidratado de limon y cogollo de menta fresca.","de":"paso"}],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGRIAS","decoracion":[],"presentacion":"JARRA:Decanter grande con picadillo y los liquidos menos el vino, este se sirve a modo de experiencia al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"25.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C25C', 'bebida', 'GREEN VELVET (COPA)', 'Inspirada en la lulada valluna, de perfil fresco, cítrico y ligeramente especiado, donde el lulo, el kiwi y el melón aportan una base tropical que se mezcla con la intensidad del limoncello y el licor de limoncillo, mientras el ron y el vino blanco equilibran la mezcla; el zumo de mandarina y el sirope de clavo y canela realzan sus notas aromáticas, dando como resultado una bebida vibrante, refrescante y bien balanceada', 1, 'und', '{}'::text[], '1) Agregar la fruta picada, los licores y el zumo de mandarina a un primer tiempo (vaso pequeño del shake) y presionar con ayuda del macerador con mucha suavidad para soltar la fruta. 2) Pasar el contenido a la copa y añadir 90 gr de hielo. 3) Agregar el sirope de morfeo pee y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa 4) Agregar con cuidado la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar.', '[{"tipo":"ing","codigo":"BAR-picadillo-green-velvet","nombre":"Picadillo green velvet","cantidad":2,"unidad":"cda","nota":null},{"tipo":"ing","codigo":"BAR-limoncello","nombre":"Limoncello","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-limoncillo","nombre":"Licor de limoncillo","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-green-velvet","nombre":"Sirope green velvet","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-blanco","nombre":"Vino blanco","cantidad":150,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-mandarina","nombre":"Zumo de mandarina","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron","nombre":"Ron","cantidad":15,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar la fruta picada, los licores y el zumo de mandarina a un primer tiempo (vaso pequeño del shake) y presionar con ayuda del macerador con mucha suavidad para soltar la fruta.","Pasar el contenido a la copa y añadir 90 gr de hielo.","Agregar el sirope de morfeo pee y despues con ayuda de un barspoom de pomo rojo verter el vino de modo que este al caer genere dos tonalidades en la copa","Agregar con cuidado la medialuna de naranja y coronar con el deshidratado y el cogollo de menta francesa y despacahar."],"puntos":[],"observaciones":[],"metodo":"Directo, Experiencia","concepto":"SANGRIAS","decoracion":[],"presentacion":"Copa balon corugada con una doble tonalidad o contraste entre los licores con el picadillo de fruta y el vino junto a un coronado estetico","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"25.5","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C26', 'bebida', 'NETARE DI CARNALE', 'Deliciosa y sofisticada donde el licor de durazno aporta dulzura frutal, equilibrada por la acidez del zumo de naranja. El vodka da cuerpo limpio, mientras el sirope de cardamomo añade un toque especiado y exótico. Se finaliza con espumante Baron de Rotbergh, que integra todo con burbujas finas y un cierre fresco y elegante.', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo (vaso corto del shake) el licor de durazno, el vodka, el zumo de limon y el sirope de cardamomo. 2] Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos). 3] Verter la mezcla en la copa flauta previamente decorada y terminar añaiendo nuestro proseco mioneto sin mezclar. 4] Agregar un dash de la mezcla de las cerezas maceradas en vermouth, decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho.', '[{"tipo":"ing","codigo":"BAR-licor-de-durazno-convier","nombre":"Licor de durazno convier","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vodka-absolut","nombre":"Vodka absolut","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naranja","nombre":"Zumo de naranja","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-cardamomo","nombre":"Sirope de cardamomo","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-espumante","nombre":"vino espumante","cantidad":90,"unidad":"ml","nota":"vino espumante (baron de rothberg)"}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto del shake) el licor de durazno, el vodka, el zumo de limon y el sirope de cardamomo.","Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos).","Verter la mezcla en la copa flauta previamente decorada y terminar añaiendo nuestro proseco mioneto sin mezclar.","Agregar un dash de la mezcla de las cerezas maceradas en vermouth, decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho."],"puntos":[],"observaciones":[],"metodo":"Directo","concepto":"COCTELERIA DE AUTOR","decoracion":["Pincho con esferas de durazno congeladas"],"presentacion":"Copa flauta previemente labiada con miel de agave y escarcha comestible azul rey ccon pincho de cereza, duraazno en almíbar y deshidratado de limón","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"26.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C27', 'bebida', 'MIMOSA DE FUEGO', 'Audaz y vibrante donde el tequila y el mezcal suman carácter, con notas ahumadas y agave profundo. El chamoy da un contraste dulce, ácido y ligeramente picante, mientras el zumo de mandarina aporta frescura cítrica. El espumante Baron de Rotbergh, da equilibra con burbujas finas y un final refrescante y atrevido.', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo (vaso corto del shake) el mezcal, el tequila, el zumo de mandarina, el sirope de romero y el sirope de chamoy. 2] Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos). 3] Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar. 4] Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho.', '[{"tipo":"ing","codigo":"BAR-mezcal-montelobos","nombre":"mezcal montelobos","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-tequila","nombre":"tequila","cantidad":10,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-espumante","nombre":"espumante","cantidad":120,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-romero","nombre":"Sirope De Romero","cantidad":null,"unidad":"dash","nota":"DASH"},{"tipo":"ing","codigo":"BAR-zumo-de-naranja","nombre":"zumo de naranja","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-chamoy","nombre":"Sirope De Chamoy","cantidad":25,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto del shake) el mezcal, el tequila, el zumo de mandarina, el sirope de romero y el sirope de chamoy.","Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos).","Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar.","Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho."],"puntos":[],"observaciones":[],"metodo":"Low shake,directo","concepto":"COCTELERIA DE AUTOR","decoracion":["Labiado de Tajín","Chile deshidratado"],"presentacion":"Copa flauta escarchada con base de salsa chamoy, sal de fresa y un deshidratado de chile al lado de la preparación pincho con parisien (bola de sandía bañada en chamoy fungiendo como mezclador (experiencia en mesa de vertido de el espumante al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"27.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C28', 'bebida', 'MIMOSA DE AGUA', 'Exotica, fresca y aromática donde el curaçao aporta notas cítricas y un sutil dulzor, mientras el pisco da carácter elegante y frutal, la mandarina realza la acidez jugosa, y el espumante Baron de Rotbergh integra todo con burbujas finas, dejando un final equilibrado, ligero y refrescante.', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo (vaso corto del shake) el triple sec azul, el pisco, y el zumo de mandarina. 2] Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos). 3] Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar. 4] Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho.', '[{"tipo":"ing","codigo":"BAR-triple-sec-azul","nombre":"triple sec azul","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-mix-de-citricos","nombre":"mix de citricos","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-pisco-demonio-de-los-andes","nombre":"pisco demonio de los andes","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-orange-bitters","nombre":"orange bitters","cantidad":5,"unidad":"gts","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-mandarina","nombre":"zumo de mandarina","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-espumante","nombre":"vino espumante","cantidad":120,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto del shake) el triple sec azul, el pisco, y el zumo de mandarina.","Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos).","Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar.","Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho."],"puntos":[],"observaciones":[],"metodo":"Low shake,directo","concepto":"COCTELERIA DE AUTOR","decoracion":["Falso coral azul","Labiado de azúcar y ácido cítrico"],"presentacion":"Copa flauta labiada con mix de cítricos coronada con un falso coral color azul y un pincho con arándanos funjiendo como mezclador (experiencia en mesa de vertido de el espumante al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"28.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C29', 'bebida', 'MIMOSA DE VIENTO', 'Suave y citrica, donde el néctar de manzana y pera aporta dulzura fresca. El licor Soho añade un toque frutal exótico y el vodka da estructura limpia. Las rodajas de limón Tahití y lima con azúcar intensifican el contraste cítrico-dulce, y el espumante armoniza con un final ligero y refrescante.', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo (vaso corto del shake) el vodka, el soho, el zumo de manzana-pera, y el mix de citricos. 2] Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos). 3] Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar. 4] Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho.', '[{"tipo":"ing","codigo":"BAR-soho","nombre":"soho","cantidad":10,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vodka","nombre":"vodka","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-jugo-de-lychee","nombre":"Jugo de lychee","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-mix-de-citricos","nombre":"mix de citricos","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-espumante","nombre":"vino espumante","cantidad":90,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto del shake) el vodka, el soho, el zumo de manzana-pera, y el mix de citricos.","Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos).","Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar.","Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho."],"puntos":[],"observaciones":[],"metodo":"Low shake,directo","concepto":"COCTELERIA DE AUTOR","decoracion":["Pincho con 1und de lychee"],"presentacion":"Copa flauta labiada con mix de cítricos y escarchada con azúcar cítrica y escarcha de brillantina blanca con deshidratado de manzana y un pincho de lychee fungiendo como mezclador","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"29.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C30', 'bebida', 'MIMOSA DE TIERRA', 'Exótica y almendrada mezcla, donde el tamarindo aporta acidez dulce, el Licor 43 notas cálidas y el ron de banano un perfil tropical. El zumo de naranja refresca, el romero añade un toque herbal, y el espumante Baron de Rotberhg cierra con un final ligero y aromático', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo (vaso corto del shake) concentrado de romero, el ron de banano, el licor 43, el zumo de naranja y el sirope de tamarindo. 2] Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos). 3] Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar. 4] Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho.', '[{"tipo":"ing","codigo":"BAR-concentrado-de-romero","nombre":"concentrado de romero","cantidad":null,"unidad":"dash","nota":"DASH"},{"tipo":"ing","codigo":"BAR-sirope-de-tamarindo","nombre":"Sirope De Tamarindo","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-naranja","nombre":"zumo de naranja","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-43","nombre":"licor 43","cantidad":10,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ron-de-banano","nombre":"ron de banano","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-espumante","nombre":"vino espumante","cantidad":120,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto del shake) concentrado de romero, el ron de banano, el licor 43, el zumo de naranja y el sirope de tamarindo.","Agregar una palada pequeña de hielo (menos de la mitad del segundo tiempo) y agitar suave y brevemente (low shake, solo 5 segundos).","Verter la mezcla en la copa flauta previamente decorada y terminar añadiendo nuestro proseco mioneto sin mezclar.","Decorar y despachar, explicar al asesor de servicio la indicacion al comensal de revolver la mimosa con el mismo pincho."],"puntos":[],"observaciones":[],"metodo":null,"concepto":"COCTELERIA DE AUTOR","decoracion":["Banano deshidratado"],"presentacion":"Copa flauta labiada con sirope de tamarindo y escarchado con escarcha comestible blanco brillante y un pincho con una parisien de banano fungiendo como mezclador (experiencia en mesa de vertido de el espumante al frente del comensal","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"30.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C31', 'bebida', 'AZURRO ABISALE', 'Un cóctel fresco y aromático donde la menta francesa majada con sirope simple libera notas herbales intensas, equilibradas por el zumo de limón y el ron. El triple sec azul aporta un toque cítrico y vibrante, mientras el vino rosado añade ligereza frutal y el dash de soda cierra con un final suave y refrescante.', 1, 'und', '{}'::text[], '1] Agregar a la copa la menta francesa, el ron bacardi añejo, el sirope simple y el zumo de limon, majamos muy bien y mezclamos 2] llenar la copa a tope de hielo y agregar con ayuda del barspoom el triple sec azul de modo que se genere una segunda capaseguido de las rodajas de citricos a los lados de igual manera procurando no mezclar el coctel, 3] Agregar con la ayuda del barspoom el vino rosado, nuevamente procurando en este caso crear una tercera capa dividida. 4] Para finalizar la preparación agregamos un dash de soda muy suavemente para agregar una ligera gasificacion, decorar y despachar.', '[{"tipo":"ing","codigo":"BAR-ron-bacardi","nombre":"Ron bacardi","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-triple-sec-azul-convier","nombre":"Triple sec azul convier","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vino-rosaleda-rose","nombre":"Vino rosaleda rose","cantidad":120,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-soda-swepers","nombre":"Soda swepers","cantidad":null,"unidad":"dash","nota":"DASH"}]'::jsonb, '{"pasos":["Agregar a la copa la menta francesa, el ron bacardi añejo, el sirope simple y el zumo de limon, majamos muy bien y mezclamos","llenar la copa a tope de hielo y agregar con ayuda del barspoom el triple sec azul de modo que se genere una segunda capaseguido de las rodajas de citricos a los lados de igual manera procurando no mezclar el coctel,","Agregar con la ayuda del barspoom el vino rosado, nuevamente procurando en este caso crear una tercera capa dividida.","Para finalizar la preparación agregamos un dash de soda muy suavemente para agregar una ligera gasificacion, decorar y despachar."],"puntos":[],"observaciones":[],"metodo":"Directo, En Capas","concepto":"COCTELERIA DE AUTOR","decoracion":["1UND deshidratado de limon","1UND cogollo de menta francesa"],"presentacion":"Copa balon corrugada dividida en 3 capas la primera el mojito, la segunda el triple sec azul y la tercera el vino rosado","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"31.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C32', 'bebida', 'BRISA DE JAZMIN EN PROCESO', 'Deliciosa combinacion de dulzura tropical del licor de granadilla con el carácter herbal de la ginebra, realzado por el toque cítrico del limón y la frescura de la menta francesa; el té de flor clitoria aporta un matiz floral y un color azul que vira a violeta, mientras la pimienta rosada añade un sutil picor especiado, creando una bebida equilibrada, fresca y visualmente llamativa.', 1, 'und', '{}'::text[], '1] Agregar al primer tiempo (vaso corto del shake) el licor de granadilla, la ginebra tanqueray, el zumo de limon, el te y el sirope simple', '[{"tipo":"ing","codigo":"BAR-licor-de-granadilla","nombre":"Licor de granadilla","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"ginebra tanqueray","cantidad":30,"unidad":"ml","nota":"ginebra tanqueray (solicito cambiar por bourbon o single malt para asimilarlo a un minjulep potenciado y variar el gin)"},{"tipo":"ing","codigo":"BAR-zumon-de-limon","nombre":"zumon de limon","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"Sirope simple","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-hojas-de-menta-francesa","nombre":"Hojas De Menta Francesa","cantidad":3,"unidad":"und","nota":null},{"tipo":"ing","codigo":"BAR-bitter-de-flor-clitoria","nombre":"Bitter de flor clitoria","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-pimienta-rosada","nombre":"Pimienta rosada","cantidad":3,"unidad":"g","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto del shake) el licor de granadilla, la ginebra tanqueray, el zumo de limon, el te y el sirope simple"],"puntos":[],"observaciones":["ginebra tanqueray (solicito cambiar por bourbon o single malt para asimilarlo a un minjulep potenciado y variar el gin)"],"metodo":"Shake,Experiencia","concepto":"COCTELERIA DE AUTOR","decoracion":[],"presentacion":"Copa coñac Labiada con azúcar cítrica y escarcha comestible violeta con experiencia en mesa añadiendo gotas de concentrado de flor clitoria","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"32.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C33', 'bebida', 'MANZANILLA ROYALE', 'Combina la suavidad floral del licor de manzanilla con el carácter seco y botánico de la Tanqueray, equilibrado por la profundidad dulce y especiada del vermouth rosso y el amargor distintivo del Campari; los orange bitters aportan un toque cítrico y aromático que redondea la mezcla, dando como resultado una bebida compleja, elegante y de perfil amargo-dulce.', 1, 'und', '{}'::text[], '1] Agregar al mix in glass el licor de manzanilla, la ginebra, el vermouth y el campari. 2] Llenar a tope el mix in glass con hielo y con ayuda del barspoom oro rosa refrescamos rapidamente hasta generar brillo en la temperatura (tambien se puede corroborar viendo que al nivel del liquido se hace una capa de frio). 3] Una vez refrescado con ayuda del colador de oruga y el colador de mala fina verter la copa en el vaso previamente refrigerado, aegregar el orange bitters decorar y despachar', '[{"tipo":"ing","codigo":"BAR-licor-de-manzanilla","nombre":"Licor De Manzanilla","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"ginebra tanqueray","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vermouth-rosso","nombre":"vermouth rosso","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-campari","nombre":"campari","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-orange-bitters","nombre":"orange bitters","cantidad":3,"unidad":"gts","nota":null}]'::jsonb, '{"pasos":["Agregar al mix in glass el licor de manzanilla, la ginebra, el vermouth y el campari.","Llenar a tope el mix in glass con hielo y con ayuda del barspoom oro rosa refrescamos rapidamente hasta generar brillo en la temperatura (tambien se puede corroborar viendo que al nivel del liquido se hace una capa de frio).","Una vez refrescado con ayuda del colador de oruga y el colador de mala fina verter la copa en el vaso previamente refrigerado, aegregar el orange bitters decorar y despachar"],"puntos":[],"observaciones":[],"metodo":"Escanseado O Refrescado, Doble Colado","concepto":"COCTELERIA DE AUTOR","decoracion":["Hielo perfect con flor de manzanilla dentro","Cáscara de naranja"],"presentacion":"En vaso rockero rociado con los aceites de la cáscara de naranja y piel de naranja y deshidratado de naranja (hielo esférico con flores de manzanilla en su interior","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"33.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C34', 'bebida', 'GOLDEN PINEFIZZ', 'Deliciosa mezcla con un toque seco y botánico de la Tanqueray con la acidez vibrante del zumo de limón, equilibrado por la dulzura tropical de la piña (Pinefizz) y el toque herbal del sirope de romero; el Fizzi frizzante rosé aporta efervescencia y un matiz afrutado, dando como resultado una bebida fresca, aromática y refrescante.', 1, 'und', '{}'::text[], '1) Agregar al primer tiempo (vaso corto del shake a un shake agregando el hielo a la mitad del segundo tiempo (vaso largo del shake) y agitando fuerte y rapidamente (low shake) por 5 segundos. 2) verter en un vaso collins zac previemente enfriado con hielo largo. 3) Una vez vertida la mezcla decorar y despachar junto a la lata de fizzy para ser servida en mesa dejadola lata con el restante en mesa e ir sirviendo poco a poco o indicarle al comensal que lo puede ir agregando.', '[{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"ginebra tanqueray","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"zumo de limon","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-pinefizz","nombre":"sirope pinefizz","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-coctel-en-lata-jp","nombre":"Cóctel en lata JP","cantidad":1,"unidad":"lata","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-romero","nombre":"sirope de romero","cantidad":15,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar al primer tiempo (vaso corto del shake a un shake agregando el hielo a la mitad del segundo tiempo (vaso largo del shake) y agitando fuerte y rapidamente (low shake) por 5 segundos.","verter en un vaso collins zac previemente enfriado con hielo largo.","Una vez vertida la mezcla decorar y despachar junto a la lata de fizzy para ser servida en mesa dejadola lata con el restante en mesa e ir sirviendo poco a poco o indicarle al comensal que lo puede ir agregando."],"puntos":[],"observaciones":[],"metodo":"Low shake, Directo","concepto":"COCTELERIA DE AUTOR","decoracion":["Labiado con miel de agave y Tajín","Piña deshidrata dorada","Romero"],"presentacion":"En vaso Collin''s corrugado Labiado con miel (de agave) dorada rociada con Tajín y decorado con deshidratado de piña y limón (ambas barnizadas con miel dorada con la experiencia en mesa del vertido de la lata de JP","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"34.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C35', 'bebida', 'SCARLET KISS', 'Coctel con carácter vibrante del tequila con la acidez del zumo de limón y el dulzor cítrico del triple sec, realzado por el sirope Scarlet Kiss (con notas de fresa, albahaca y canela cassia) que aporta un perfil frutal, herbal y ligeramente especiado, mientras el licor de menta fresca añade un contraste refrescante; servido granizado, resulta una bebida intensa, equilibrada y muy refrescante..', 1, 'und', '{}'::text[], '1) Agregar todos los ingredientes a la licuadora. 2) Agregar una palada de hielo (importante para la consistencia del producto un hielo grueso y bien congelado valga la redundancia). 3) Vertir en una copa margarita previamente enfriada y michelada con sal de fresa media parte y la otra media con azucar morena. 4) Coronar con una rodaja de fresa fresca,una hoja de menta y una astilla larga de canela cassia la cual el asesor encendera en mesa por lo cual tiene que estar ligeramente sobresalida para facilitar el flameado.', '[{"tipo":"ing","codigo":"BAR-sirope-scarlet-kiss","nombre":"Sirope Scarlet Kiss","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-tequila","nombre":"Tequila","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo De Limon","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-triple-sec","nombre":"Triple Sec","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-menta-fresca","nombre":"Licor De Menta Fresca","cantidad":15,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar todos los ingredientes a la licuadora.","Agregar una palada de hielo (importante para la consistencia del producto un hielo grueso y bien congelado valga la redundancia).","Vertir en una copa margarita previamente enfriada y michelada con sal de fresa media parte y la otra media con azucar morena.","Coronar con una rodaja de fresa fresca,una hoja de menta y una astilla larga de canela cassia la cual el asesor encendera en mesa por lo cual tiene que estar ligeramente sobresalida para facilitar el flameado."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar una palada de hielo (importante para la consistencia del producto un hielo grueso y bien congelado valga la redundancia).","de":"paso"}],"observaciones":[],"metodo":"Frozen","concepto":"COCTELERIA DE AUTOR","decoracion":["1UND Canela cassia","1UND hoja de albahaca"],"presentacion":"Copa martini premium con la mitad escarchada con sal de fresa y coronada con deshidratado de limón unas cuantas pepas de pimienta rosada y una canela sobresaliendo en la copa para experiencia del ahumado de canela","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"35.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C36', 'bebida', 'JAMAITINI', 'Deicioso y con carácter, floral y ligeramente ácido del licor de jamaica con el perfil seco del vermouth extra dry y botánico de la Tanqueray, equilibrado por la dulzura herbal del sirope de romero; el mix de cítricos aporta una acidez fresca y redondeada, dando como resultado una bebida aromática, equilibrada y refrescante con un sutil fondo herbal.', 1, 'und', '{}'::text[], '1) Agregar todos los liquidos al mix in glass 2) Agregar hielo full (procurar que sea un hielo compacto y bien congelado), y proceder a frefrescar. 3) Servir en una copa martini premium brochada con glaseado de flor de jamaica y un pincho de 1 lychee con 2 flores de jamaica glaseada y una naranja glaseada y despachar.', '[{"tipo":"ing","codigo":"BAR-licor-de-jamaica","nombre":"Licor de jamaica","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-vermouth-extra-dry","nombre":"vermouth Extra Dry","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-romero","nombre":"sirope de romero","cantidad":null,"unidad":"dash","nota":"DASH"},{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"Ginebra tanqueray","cantidad":30,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar todos los liquidos al mix in glass","Agregar hielo full (procurar que sea un hielo compacto y bien congelado), y proceder a frefrescar.","Servir en una copa martini premium brochada con glaseado de flor de jamaica y un pincho de 1 lychee con 2 flores de jamaica glaseada y una naranja glaseada y despachar."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar hielo full (procurar que sea un hielo compacto y bien congelado), y proceder a frefrescar.","de":"paso"}],"observaciones":[],"metodo":"Refrescado o Escanseado, Doble Colado","concepto":"COCTELERIA DE AUTOR","decoracion":["Aceituna negra","Deshidratado de naranja"],"presentacion":"Copa Martini con una aceituna negra en el fondo de la copa y la naranja deshidratada","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"36.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C37', 'bebida', 'PINKY PROMISE', 'Deliciosa y sumamente refrescante fusion del perfil afrutado de la Beefeater Pink con la acidez del zumo de limón y el carácter cítrico del sirope de naranja agria, complementado por las notas florales del licor de jamaica; la tónica de manzana aporta frescura y efervescencia, mientras los trozos de sandía intensifican el perfil refrescante y jugoso, dando como resultado una bebida ligera, aromática y veraniega.', 1, 'und', '{}'::text[], '1) Labiar y congelar previamente el vaso con 15ML de ginebra (la idea es aromatizar el interior del vaso con ese toque de gin). 2) Agregar al primer tiempo (vaso corto del shake) los 45ML del gin restante junto a el sirope el licor de jamaica y el zumo de limon, 3) Agregamos en el segundo tiempo (vaso largo del hsake) hielo hasta la mitad yprocedemos a agitar con fuerza por un corto periodo de tiempo- 8 segundos. 4) Disponemos de vaso alistado y agregamos hielo a tope, vertir el coctel seguido de los trozos de sandia. 5) Para finalizar agregamos la 976 de manzana removemos de manera ascendente, decorar y despachar (la 976 la dejamos con el comensal)..', '[{"tipo":"ing","codigo":"BAR-ginebra-beefeater-pink","nombre":"Ginebra beefeater pink","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-naranja-agria","nombre":"Sirope De naranja agria","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-flor-de-jamaica","nombre":"licor de flor de jamaica","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"zumo de limon","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-mil-976-de-manzana","nombre":"Mil 976 de manzana","cantidad":1,"unidad":"bot","nota":null},{"tipo":"ing","codigo":"BAR-trozos-de-sandia","nombre":"Trozos de sandia","cantidad":20,"unidad":"g","nota":null}]'::jsonb, '{"pasos":["Labiar y congelar previamente el vaso con 15ML de ginebra (la idea es aromatizar el interior del vaso con ese toque de gin).","Agregar al primer tiempo (vaso corto del shake) los 45ML del gin restante junto a el sirope el licor de jamaica y el zumo de limon,","Agregamos en el segundo tiempo (vaso largo del hsake) hielo hasta la mitad yprocedemos a agitar con fuerza por un corto periodo de tiempo- 8 segundos.","Disponemos de vaso alistado y agregamos hielo a tope, vertir el coctel seguido de los trozos de sandia.","Para finalizar agregamos la 976 de manzana removemos de manera ascendente, decorar y despachar (la 976 la dejamos con el comensal).."],"puntos":[{"tipo":"TEMPERATURA","texto":"Labiar y congelar previamente el vaso con 15ML de ginebra (la idea es aromatizar el interior del vaso con ese toque de gin).","de":"paso"}],"observaciones":[],"metodo":"Low Shake, Directo","concepto":"COCTELERIA DE AUTOR","decoracion":["Trozos de sandía","1UND Menta francesa"],"presentacion":"Vaso collins Zac con media parte labiada con azucar blanca y acido citrico con trozos de sandia y coronado con un pincho de gomitas y naranja glaseada","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"37.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C38', 'bebida', 'LOOMP', 'Este cóctel combina la cremosidad dulce del Baileys con el carácter intenso del tequila de chocolate, equilibrado por la frescura ácida del mix de cítricos; el helado de macadamia aporta una textura suave, untuosa y un fondo tostado y ligeramente dulce, dando como resultado una bebida tipo dessert cocktail, cremosa, refrescante y con un contraste entre lo cítrico, lo achocolatado y lo nuez.', 1, 'und', '{}'::text[], '1) Agregar todos los liquidos a nuestra licuadora. 2) Agregar 2 bolas de helado medianas procurando que lleguen al fondo del vaso. 3) Agregar hielo (100GR), procurando que este este firme y bien congelado, proceder a licuar oprimiendo el boton FROZEN dejando que culmine su preparacion. 4) Vertir en una copa martini premium previamente refrigerada con una cobertura de chocolate herseys y coronar con una rodaja glaseada de naranja, un corazon de chocolate hersey''s y una cereza macerada en vermouth.', '[{"tipo":"ing","codigo":"BAR-mix-citricos","nombre":"mix citricos","cantidad":25,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-baeilys","nombre":"baeilys","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-tequila-de-chocolate","nombre":"Tequila de chocolate","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-helado-de-artesanal","nombre":"helado de artesanal","cantidad":1,"unidad":"bola grande","nota":null}]'::jsonb, '{"pasos":["Agregar todos los liquidos a nuestra licuadora.","Agregar 2 bolas de helado medianas procurando que lleguen al fondo del vaso.","Agregar hielo (100GR), procurando que este este firme y bien congelado, proceder a licuar oprimiendo el boton FROZEN dejando que culmine su preparacion.","Vertir en una copa martini premium previamente refrigerada con una cobertura de chocolate herseys y coronar con una rodaja glaseada de naranja, un corazon de chocolate hersey''s y una cereza macerada en vermouth."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregar hielo (100GR), procurando que este este firme y bien congelado, proceder a licuar oprimiendo el boton FROZEN dejando que culmine su preparacion.","de":"paso"}],"observaciones":[],"metodo":"Frozen","concepto":"COCTELERIA DE AUTOR","decoracion":["1UND Cereza macerada en vermouth","Salsa hersey''s de chhocolate"],"presentacion":"Copa martini premium preciamente dibujada con salsa de chocolate y refrigerada coronada con pincho de cereza y glaseado y un corazon dibujado (con hersey''s)","alergenos_declarados":[],"alergenos_sugeridos":["Lácteos","Sulfitos"],"numero":"38.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C39', 'bebida', 'SOUR CAFÉ ALMENDRADO', 'Esplendida mezcla quecombina la dulzura almendrada del Amaretto Disaronno con la acidez del zumo de limón y la suavidad del sirope simple, mientras la clara de huevo se incorpora para aportar la textura característica espumosa y sedosa del clásico sour; la espuma de café añade un toque aromático y ligeramente amargo que equilibra el conjunto, resultando en una bebida cremosa, elegante y bien balanceada entre dulce, ácido y tostado.', 1, 'und', '{}'::text[], '1) Agregar la clara de un huevo (recien extraida, muy importante) 2) Agregar el amareto , el zumo de limon, el sirope simple y el resorte de un colador de oruga y sin agregar hielo tapamos y agitamos con bastante furza por un periodo de tiempo prolongado 30seg aprox, 3) Destapamos el shake, retiramos el resorte y agregamos el hielo, nuevamente tapando y agitando con mucha fuerza. 4) Vertir en la copa previamente refrigerada y coronar con 3 gotas de angostura y una cascara de glaseado. 5) Indicar a nuestros asesores de servicio la aplicacion de 1 suspiro o espiral de nuestra espuma de cafe procurando que quede compacta.', '[{"tipo":"ing","codigo":"BAR-amareto-dissarono","nombre":"Amareto dissarono","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-clara-de-huevo","nombre":"clara de huevo","cantidad":1,"unidad":"und","nota":null},{"tipo":"ing","codigo":"BAR-sirope-simple","nombre":"sirope simple","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"zumo de limon","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-espuma-de-cafe","nombre":"Espuma de café","cantidad":null,"unidad":null,"nota":"Para coronar"},{"tipo":"ing","codigo":"BAR-amargos-de-angostura","nombre":"Amargos de angostura","cantidad":3,"unidad":"gota","nota":null}]'::jsonb, '{"pasos":["Agregar la clara de un huevo (recien extraida, muy importante)","Agregar el amareto , el zumo de limon, el sirope simple y el resorte de un colador de oruga y sin agregar hielo tapamos y agitamos con bastante furza por un periodo de tiempo prolongado 30seg aprox,","Destapamos el shake, retiramos el resorte y agregamos el hielo, nuevamente tapando y agitando con mucha fuerza.","Vertir en la copa previamente refrigerada y coronar con 3 gotas de angostura y una cascara de glaseado.","Indicar a nuestros asesores de servicio la aplicacion de 1 suspiro o espiral de nuestra espuma de cafe procurando que quede compacta."],"puntos":[{"tipo":"CALIDAD","texto":"Agregar la clara de un huevo (recien extraida, muy importante)","de":"paso"}],"observaciones":[],"metodo":"Dry Shake y Hard Shake, finalizado En Mesa","concepto":"COCTERIA DE AUTOR","decoracion":["Espuma de café","granos de café"],"presentacion":"Copa cupé, de un lado gotas de angostura esteticas con el glaseado, se finaliza agregando espuma en mesa","alergenos_declarados":[],"alergenos_sugeridos":["Huevo","Frutos secos"],"numero":"39.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C40', 'bebida', 'MENJURJE DE LAS DRIADES', 'Esplendia combinacion con el carácter botánico de la Tanqueray y intensidad herbal del Jägermeister, equilibrado por la frescura ácida del mix de cítricos y la dulzura aromática del sirope de romero; el licor de menta fresca aporta un toque refrescante adicional, mientras la tónica suma burbujas y ligereza, dando como resultado una bebida herbal, fresca y compleja con un final largo y refrescante.', 1, 'und', '{}'::text[], '1) Agregarel sirope, el mix de citricos, el licor de menta,y el sirope de romero al primer tiempo de shake. 2) Agregar en el segundo tiempo (vaso largo del shake) tapar y agitar. 3) Vertir el coctel en una copa coupe con un hielo y con ayuda del barspoom de pomo rojo vertir el jagermaister creando 2 tonalidades. 4) Finalizar conn un dash de agua tonica dejado la totalidad de esta para el comensal.', '[{"tipo":"ing","codigo":"BAR-sirope-de-romero","nombre":"sirope de romero","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-mix-de-citricos","nombre":"mix de citricos","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"ginebra tanqueray","cantidad":60,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-menta-fresca","nombre":"licor de menta Fresca","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-tonica","nombre":"tonica","cantidad":1,"unidad":"bot","nota":null},{"tipo":"ing","codigo":"BAR-jagermaister","nombre":"Jagermaister","cantidad":15,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregarel sirope, el mix de citricos, el licor de menta,y el sirope de romero al primer tiempo de shake.","Agregar en el segundo tiempo (vaso largo del shake) tapar y agitar.","Vertir el coctel en una copa coupe con un hielo y con ayuda del barspoom de pomo rojo vertir el jagermaister creando 2 tonalidades.","Finalizar conn un dash de agua tonica dejado la totalidad de esta para el comensal."],"puntos":[],"observaciones":[],"metodo":"Shake, En Capas","concepto":"COCTELERIA DE AUTOR","decoracion":["1UND Glaseado de limon","1UND Rama de romero"],"presentacion":"Copa de vino corrugado con una tonalidad superior proporcionada por el jagermaister coronado con glaseado de naranja y una rama de romero para ahumar en mesa","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"40.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C42', 'bebida', 'ALCABULLET', 'Robusto, delicioso y sofisticado, con la fuerza del Bulleit Bourbon con la dulzura ahumada del sirope de tabaco y cáscara de naranja importada, equilibrado por la profundidad herbal del vermouth rosso y la acidez del zumo de limón; la sal rosada potencia los sabores y aporta un toque mineral que redondea el conjunto, dando como resultado una bebida intensa, compleja y con un perfil amargo-dulce muy equilibrado.', 1, 'und', '{}'::text[], '1) Agregar todos los liquidos al mix in glass a excepcion y agregar 3 giros del molino de la sal rosada (si se va a hacer refrescado diluir la sal con ayuda del barspoom oro rosa antes de agregar el hielo. 2) Agregarhielo full y proceder a refrescar (muy importante que sea hielo compacto y bien congelado. 3) Verter en un vaso rockero previamente enfriado con hielo perfect y una rodaja de naranja coronar con fideos de naranja glaseada de forma que se decore el centro del coctel y a uyn extremo la rama de romero. 4) Despachar y indicar al mesero flamear el romero al lado contrario del comensal.', '[{"tipo":"ing","codigo":"BAR-sirope-de-tabaco-y-cascara-de-naranja-im","nombre":"sirope de tabaco y cascara de naranja importada","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-whisky-bullet-bourbon","nombre":"whisky bullet bourbon","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sal-rosada","nombre":"Sal Rosada","cantidad":3,"unidad":"g","nota":null},{"tipo":"ing","codigo":"BAR-vermouth-rosso","nombre":"vermouth rosso","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"zumo de limon","cantidad":15,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Agregar todos los liquidos al mix in glass a excepcion y agregar 3 giros del molino de la sal rosada (si se va a hacer refrescado diluir la sal con ayuda del barspoom oro rosa antes de agregar el hielo.","Agregarhielo full y proceder a refrescar (muy importante que sea hielo compacto y bien congelado.","Verter en un vaso rockero previamente enfriado con hielo perfect y una rodaja de naranja coronar con fideos de naranja glaseada de forma que se decore el centro del coctel y a uyn extremo la rama de romero.","Despachar y indicar al mesero flamear el romero al lado contrario del comensal."],"puntos":[{"tipo":"TEMPERATURA","texto":"Agregarhielo full y proceder a refrescar (muy importante que sea hielo compacto y bien congelado.","de":"paso"}],"observaciones":[],"metodo":"Escanseado o Refrescado","concepto":"COCTELERIA DE AUTOR","decoracion":["Espiral de fideos de narnaja confitados","1UND Medialuna de naranja","1UND Rama de rmero (para flamear)"],"presentacion":"vaso rockero o corto previamente enfriado con hielo perfect una medialuna de naranja al lado y coronado con fideos de naranja confitada y una rama de romero para flamear en mesa","alergenos_declarados":[],"alergenos_sugeridos":["Sulfitos"],"numero":"42.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C43', 'bebida', 'IMPERATORE MEXICA', 'Exotica combinacion de ahumado del mezcal con la acidez nuestro mix de cítricos y el dulzor herbal del licor de limoncillo potenciado por el licor de chile ancho dando un toque sutilmente picante y profundo.y con nuestra inyeccion de c02 la mezcla, suma una textura burbujeante que realza sus aromas y lo convierte en una experiencia vibrante y refrescante en cada sorbo.', 1, 'und', '{}'::text[], '1] Tomar el vaso collins tiki, labiarlo y llevarlo a refrigeracion 2] Agregar al primer tiempo (vaso corto del shake) el mezcal, el licor de limoncillo, el licor de chile ancho y el mix de citricos, llenar el segundo tempo a la mitad del hielo sellar y agitar. 3] Una vez agitado vertimos la mezcla en el gasificador y junto con el caso collins tiki ya frio, decorado y con hielo a tope 4) Explicar al asesor de servicio sobre el proceso de gasificacion (sellar el recipiente en su totalidad dejando que la bala libere el c02 esperando a que el liquido gasifique seguido de abrir el recipiente lentamente para que el exceso de gas se libere lentamente mas no se desgasifique y procesder a servir en nuestro vaso collins tiki.', '[{"tipo":"ing","codigo":"BAR-mezcal-montelobos","nombre":"Mezcal montelobos","cantidad":45,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-limoncillo","nombre":"licor de limoncillo","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-chile-ancho","nombre":"licor de chile ancho","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-mix-de-citricos","nombre":"mix de citricos","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-bala-de-co2","nombre":"bala de co2","cantidad":1,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Tomar el vaso collins tiki, labiarlo y llevarlo a refrigeracion","Agregar al primer tiempo (vaso corto del shake) el mezcal, el licor de limoncillo, el licor de chile ancho y el mix de citricos, llenar el segundo tempo a la mitad del hielo sellar y agitar.","Una vez agitado vertimos la mezcla en el gasificador y junto con el caso collins tiki ya frio, decorado y con hielo a tope","Explicar al asesor de servicio sobre el proceso de gasificacion (sellar el recipiente en su totalidad dejando que la bala libere el c02 esperando a que el liquido gasifique seguido de abrir el recipiente lentamente para que el exceso de gas se libere lentamente mas no se desgasifique y procesder a servir en nuestro vaso collins tiki."],"puntos":[],"observaciones":[],"metodo":"Shake, Gasificacion","concepto":"COCTELERIA DE AUTOR","decoracion":["Sal con ácido cítrico (Labiado)","1UND Garnitura de limon","1UND Rama de romero"],"presentacion":"Vaso collins tiki previamente enfriado y labiado el cual sale solamente con hielo la garnitura y una rama de romero el coctel sale en el gasificador el cual nuestro asesor de ventas lleva a mesa y activa al frente de los comensales y una vez gasificado se vierte en el vaso","alergenos_declarados":[],"alergenos_sugeridos":[],"numero":"43.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C44', 'bebida', 'BIRRA PRIMAVERAL', '“Birra Envenenada” es un cóctel audaz y refrescante que mezcla lo frutal de la cerveza BBC Rosada con las notas florales del licor de jamaica y el perfil aromático de la ginebra ademas. El sirope de chamoy añade un contraste dulce, ácido y ligeramente salado, ademas el limón intensifica la frescura, logrando una bebida vibrante, atrevida y con un balance perfecto entre frutal y cítrico.', 1, 'und', '{}'::text[], '1] Labiar un vaso collins corrugado con sal de fresa (barnis de chamoy) y agregar al vaso 15ML de befeater pink y 15ML de sirope de chamoy, refrigerar. 2] Agregar a nuestra posima (minibotella de vidrio) el licor de jamaica el restante de ginebra y chamoy y el zumo de limon, tapar y agitar. 3] Una vez refrigerado llenar a tope de hielo, agregar las laminas de fresa y despachar indicando al asesor servirlo de la siguiente manera: -Se agrega primero la cerveza con el vaso inclinado 45 grados y se deja al comensal agitar la posima, asi mismo se le sugiere agregarla de manera suave para que evidencie como se difumina lentamente y se mezcla con la cerveza.', '[{"tipo":"ing","codigo":"BAR-cerveza-bbc-rosada","nombre":"cerveza bbc rosada","cantidad":1,"unidad":"bot","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-jamaica","nombre":"licor de jamaica","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginebra-beffeater-pink","nombre":"ginebra beffeater pink","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-chamoy","nombre":"sirope de chamoy","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"zumo de limon","cantidad":15,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Labiar un vaso collins corrugado con sal de fresa (barnis de chamoy) y agregar al vaso 15ML de befeater pink y 15ML de sirope de chamoy, refrigerar.","Agregar a nuestra posima (minibotella de vidrio) el licor de jamaica el restante de ginebra y chamoy y el zumo de limon, tapar y agitar.","Una vez refrigerado llenar a tope de hielo, agregar las laminas de fresa y despachar indicando al asesor servirlo de la siguiente manera: -Se agrega primero la cerveza con el vaso inclinado 45 grados y se deja al comensal agitar la posima, asi mismo se le sugiere agregarla de manera suave para que evidencie como se difumina lentamente y se mezcla con la cerveza."],"puntos":[],"observaciones":[],"metodo":"Directo, Pocima Di Egida","concepto":"COCTELERIA DE AUTOR","decoracion":["Sal de fresa (para labiado)","Laminas De Fresa"],"presentacion":"Vaso corugado con 2 hielos cubo, labiado y perfumado con beefeater pink,llega al comensal con su vaso decorado y perfumado junto a la cerveza y la pocima di egida los cuales son vertidos primero la cerveza seguido de la pocima","alergenos_declarados":[],"alergenos_sugeridos":["Gluten"],"numero":"44.0","responsable":"FRANCISCO GONZALES"}'::jsonb),
  ('CARTA COCTELERÍA', 'C45', 'bebida', 'BIRRA AL TAMARINDO', '“Birra Envenenada” en esta versión combina el carácter maltoso de la cerveza BBC Roja con la frescura intensa del licor de menta y la elegancia herbal de la ginebra Tanqueray. El zumo de limón aporta un toque cítrico vibrante, mientras el sirope de tamarindo suma una acidez dulce y exótica, creando un cóctel equilibrado, refrescante y con un contraste intrigante entre lo herbal, lo frutal y lo tostado.', 1, 'und', '{}'::text[], '1] Labiar un vaso collins corrugado con sal de fresa (barnis de chamoy) y agregar al vaso 15ML de tanuqeray y 15ML de sirope de tamarindo, refrigerar. 2] Agregar a nuestra posima (minibotella de vidrio) el licor de jamaica el restante de ginebra y chamoy y el zumo de limon, tapar y agitar. 3] Una vez refrigerado llenar a tope de hielo, agregar las laminas de fresa y despachar indicando al asesor servirlo de la siguiente manera: -Se agrega primero la cerveza con el vaso inclinado 45 grados y se deja al comensal agitar la posima, asi mismo se le sugiere agregarla de manera suave para que evidencie como se difumina lentamente y se mezcla con la cerveza.', '[{"tipo":"ing","codigo":"BAR-cerveza-bbc-roja","nombre":"Cerveza BBC Roja","cantidad":1,"unidad":"bot","nota":null},{"tipo":"ing","codigo":"BAR-licor-de-menta-fresca","nombre":"Licor De Menta Fresca","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-ginebra-tanqueray","nombre":"Ginebra Tanqueray","cantidad":30,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-zumo-de-limon","nombre":"Zumo De Limon","cantidad":15,"unidad":"ml","nota":null},{"tipo":"ing","codigo":"BAR-sirope-de-tamarindo","nombre":"Sirope De Tamarindo","cantidad":30,"unidad":"ml","nota":null}]'::jsonb, '{"pasos":["Labiar un vaso collins corrugado con sal de fresa (barnis de chamoy) y agregar al vaso 15ML de tanuqeray y 15ML de sirope de tamarindo, refrigerar.","Agregar a nuestra posima (minibotella de vidrio) el licor de jamaica el restante de ginebra y chamoy y el zumo de limon, tapar y agitar.","Una vez refrigerado llenar a tope de hielo, agregar las laminas de fresa y despachar indicando al asesor servirlo de la siguiente manera: -Se agrega primero la cerveza con el vaso inclinado 45 grados y se deja al comensal agitar la posima, asi mismo se le sugiere agregarla de manera suave para que evidencie como se difumina lentamente y se mezcla con la cerveza."],"puntos":[],"observaciones":[],"metodo":"Directo, Pocima Di Egida","concepto":"COCTELERIA DE AUTOR","decoracion":["Sal marina con acido citrico","Medialunas de limon"],"presentacion":"Vaso corugado, con 2 cubo , hielos labiado y perfumado con tanqueray,llega al comensal con su vaso decorado y perfumado junto a la cerveza y la pocima di egida los cuales son vertidos primero la cerveza seguido de la pocima","alergenos_declarados":[],"alergenos_sugeridos":["Gluten"],"numero":null,"responsable":"FRANCISCO GONZALES"}'::jsonb)
